### 3. Logique Métier (`js/calculator.js`)
Ce module gère exclusivement les mathématiques et l'état de la calculatrice, sans aucune manipulation du DOM.

```javascript
export const Calculator = {
    displayValue: '0',
    firstOperand: null,
    waitingForSecondOperand: false,
    operator: null,

    inputDigit(digit) {
        const { displayValue, waitingForSecondOperand } = this;

        if (waitingForSecondOperand === true) {
            this.displayValue = digit;
            this.waitingForSecondOperand = false;
        } else {
            this.displayValue = displayValue === '0' ? digit : displayValue + digit;
        }
    },

    inputDecimal(dot) {
        if (this.waitingForSecondOperand === true) return;

        if (!this.displayValue.includes(dot)) {
            this.displayValue += dot;
        }
    },

    handleOperator(nextOperator) {
        const { firstOperand, displayValue, operator } = this;
        const inputValue = parseFloat(displayValue);

        if (operator && this.waitingForSecondOperand) {
            this.operator = nextOperator;
            return;
        }

        if (firstOperand === null && !isNaN(inputValue)) {
            this.firstOperand = inputValue;
        } else if (operator) {
            const result = this.calculate(firstOperand, inputValue, operator);
            this.displayValue = `${parseFloat(result.toFixed(7))}`;
            this.firstOperand = result;
        }

        this.waitingForSecondOperand = true;
        this.operator = nextOperator;
    },

    calculate(first, second, operator) {
        switch (operator) {
            case '+': return first + second;
            case '-': return first - second;
            case '*': return first * second;
            case '/': return second !== 0 ? first / second : 'Erreur';
            default: return second;
        }
    },

    reset() {
        this.displayValue = '0';
        this.firstOperand = null;
        this.waitingForSecondOperand = false;
        this.operator = null;
    }
};
```

---

### 4. Gestion de l'Affichage (`js/ui.js`)
Ce module interagit directement avec le DOM pour mettre à jour l'écran et écouter les interactions utilisateur.

```javascript
export const UI = {
    screen: document.getElementById('display'),

    updateDisplay(value) {
        this.screen.textContent = value;
    },

    bindEvents(handlers) {
        const keys = document.querySelector('.calculator-keys');

        keys.addEventListener('click', (event) => {
            const { target } = event;
            if (!target.matches('button')) return;

            if (target.classList.contains('operator')) {
                handlers.onOperator(target.value);
                return;
            }

            if (target.classList.contains('decimal')) {
                handlers.onDecimal(target.value);
                return;
            }

            if (target.classList.contains('all-clear')) {
                handlers.onClear();
                return;
            }

            handlers.onDigit(target.value);
        });
    }
};
```

---

### 5. Point d'Entrée / Contrôleur (`js/app.js`)
Ce fichier assemble le tout en connectant les actions de l'UI à la logique métier.

```javascript
import { Calculator } from './calculator.js';
import { UI } from './ui.js';

function init() {
    // Initialisation de l'affichage
    UI.updateDisplay(Calculator.displayValue);

    // Définition des actions à effectuer lors des événements UI
    const handlers = {
        onDigit: (digit) => {
            Calculator.inputDigit(digit);
            UI.updateDisplay(Calculator.displayValue);
        },
        onDecimal: (dot) => {
            Calculator.inputDecimal(dot);
            UI.updateDisplay(Calculator.displayValue);
        },
        onOperator: (operator) => {
            Calculator.handleOperator(operator);
            UI.updateDisplay(Calculator.displayValue);
        },
        onClear: () => {
            Calculator.reset();
            UI.updateDisplay(Calculator.displayValue);
        }
    };

    // Liaison des événements
    UI.bindEvents(handlers);
}

// Lancement de l'application au chargement
document.addEventListener('DOMContentLoaded', init);
```

