        }

        .tab-btn {
            flex: 1;
            padding: 15px 20px;
            background-color: #2c3e50;
            color: #ffffff;
            border: none;
            outline: none;
            cursor: pointer;
            font-size: 16px;
            font-weight: 600;
            transition: background-color 0.3s, color 0.3s;
            text-align: center;
        }

        .tab-btn:hover {
            background-color: #34495e;
        }

        /* Style de l'onglet actif */
        .tab-btn.active {
            background-color: #ffffff;
            color: #2c3e50;
            border-top: 4px solid #3498db;
        }

        /* Contenu des pages */
        .tabs-content {
            padding: 30px;
        }

        .tab-pane {
            display: none; /* Caché par défaut */
            animation: fadeIn 0.5s ease;
        }

        /* Affichage de la page active */
        .tab-pane.active {
            display: block;
        }

        .tab-pane h2 {
            margin-bottom: 15px;
            color: #2c3e50;
        }

        .tab-pane p {
            line-height: 1.6;
            color: #666;
        }

        /* Animation d'apparition */
        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(5px); }
            to { opacity: 1; transform: translateY(0); }
        }
    </style>
</head>
