            color: var(--gray);
            font-size: 0.9rem;
            margin-bottom: 0.5rem;
        }

        .offer-card h3 {
            font-size: 1.5rem;
            margin-bottom: 1rem;
        }

        .offer-features {
            margin: 1.5rem 0;
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .offer-features li {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-size: 0.95rem;
        }

        .offer-features li::before {
            content: '✓';
            color: var(--primary);
            font-weight: bold;
        }

        .offer-price-box {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-top: 2rem;
            padding-top: 1.5rem;
            border-top: 1px solid var(--gray-light);
        }

        .offer-price {
            font-size: 1.75rem;
            font-weight: 800;
            color: var(--neutral-dark);
        }

        /* =================================================================
           9. POURQUOI NOUS CHOISIR (AVANTAGES)
           ================================================================ */
        .features {
            background-color: var(--neutral-light);
        }

        .features-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
            gap: 2rem;
        }

        .feature-item {
            background: var(--white);
            padding: 2.5rem 2rem;
            border-radius: var(--radius);
            text-align: center;
            box-shadow: var(--shadow);
            transition: var(--transition);
        }

        .feature-item:hover {
            transform: translateY(-5px);
        }

        .feature-icon {
            width: 70px;
            height: 70px;
            background-color: rgba(2, 101, 138, 0.1);
            border-radius: 50%;
            display: flex;
            align-items: center;
            justify-content: center;
            margin: 0 auto 1.5rem auto;
            color: var(--primary);
        }

        .feature-icon svg {
            width: 35px;
            height: 35px;
        }

        .feature-item h3 {
            margin-bottom: 0.75rem;
            font-size: 1.25rem;
        }

        .feature-item p {
            color: var(--gray);
            font-size: 0.95rem;
        }

        /* =================================================================
           10. À PROPOS & CHIFFRES CLÉS
           ================================================================ */
        .about-content {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 4rem;
            align-items: center;
            margin-bottom: 5rem;
        }

        .about-text h3 {
            font-size: 2rem;
            margin-bottom: 1.5rem;
            color: var(--primary-dark);
        }

        .about-text p {
            color: var(--gray);
            margin-bottom: 1.5rem;
        }

        .about-image {
            height: 400px;
            /* Placeholder CSS d'illustration */
            background: linear-gradient(135deg, var(--secondary), var(--primary));
            border-radius: var(--radius);
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--white);
            font-weight: bold;
            font-size: 1.25rem;
            box-shadow: var(--shadow);
        }

        .stats-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 2rem;
            background-color: var(--primary);
            color: var(--white);
            padding: 4rem 2rem;
            border-radius: var(--radius);
            text-align: center;
        }

        .stat-item h4 {
            font-size: 3rem;
            color: var(--secondary);
            margin-bottom: 0.5rem;
        }

        .stat-item p {
            font-size: 1.1rem;
            opacity: 0.9;
        }

        /* Équipe */
        .team-header {
            text-align: center;
            margin: 4rem 0 3rem 0;
        }

        .team-header h3 {
            font-size: 1.75rem;
            color: var(--primary-dark);
        }

        .team-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 2rem;
        }

        .team-member {
            background: var(--neutral-light);
            border-radius: var(--radius);
            overflow: hidden;
            text-align: center;
            box-shadow: var(--shadow);
        }

        .team-avatar {
            height: 200px;
            background: linear-gradient(135deg, var(--gray), var(--neutral-dark));
            display: flex;
            align-items: center;
            justify-content: center;
            color: var(--white);
            font-weight: bold;
        }

        .team-info {
            padding: 1.5rem;
        }

        .team-info h4 {
            margin-bottom: 0.25rem;
        }

        .team-info p {
            color: var(--gray);
            font-size: 0.85rem;
        }

        /* =================================================================
           11. TÉMOIGNAGES
           ================================================================ */
        .testimonials {
            background-color: var(--neutral-light);
        }

        .testimonials-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
            gap: 2rem;
        }

        .testimonial-card {
            background: var(--white);
            padding: 2.5rem;
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            position: relative;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        .testimonial-card::before {
            content: '“';
            position: absolute;
            top: 10px;
            left: 20px;
            font-size: 5rem;
            color: rgba(2, 101, 138, 0.1);
            font-family: serif;
            line-height: 1;
        }

        .testimonial-text {
            font-style: italic;
            color: var(--neutral-dark);
            margin-bottom: 2rem;
            position: relative;
            z-index: 1;
        }

        .testimonial-author {
            display: flex;
            align-items: center;
            gap: 1rem;
        }

        .author-avatar {
            width: 50px;
            height: 50px;
            border-radius: 50%;
            background-color: var(--primary);
            color: var(--white);
            display: flex;
            align-items: center;
            justify-content: center;
            font-weight: bold;
        }

        .author-info h4 {
            font-size: 1rem;
            margin-bottom: 0.1rem;
        }

        .author-info p {
            font-size: 0.8rem;
            color: var(--gray);
        }

        /* =================================================================
           12. FAQ (ACCORDÉON HTML)
           ================================================================ */
        .faq-container {
            max-width: 800px;
            margin: 0 auto;
            display: flex;
            flex-direction: column;
            gap: 1rem;
        }

        .faq-item {
            background: var(--white);
            border: 1px solid var(--gray-light);
            border-radius: var(--radius);
            overflow: hidden;
            transition: var(--transition);
        }

        .faq-item[open] {
            border-color: var(--primary);
            box-shadow: var(--shadow);
        }

        .faq-item summary {
            padding: 1.25rem 1.5rem;
            font-weight: 600;
            cursor: pointer;
            list-style: none;
            display: flex;
            justify-content: space-between;
            align-items: center;
            user-select: none;
        }

        .faq-item summary::-webkit-details-marker {
            display: none;
        }

        .faq-item summary::after {
            content: '+';
            font-size: 1.5rem;
            color: var(--primary);
            transition: var(--transition);
        }

        .faq-item[open] summary::after {
            transform: rotate(45deg);
        }

        .faq-content {
            padding: 0 1.5rem 1.5rem 1.5rem;
            color: var(--gray);
            font-size: 0.95rem;
        }

        /* =================================================================
           13. CONTACT
           ================================================================ */
        .contact {
            background-color: var(--neutral-light);
        }

        .contact-wrapper {
            display: grid;
            grid-template-columns: 1fr 1.2fr;
            gap: 4rem;
            background: var(--white);
            border-radius: var(--radius);
            box-shadow: var(--shadow);
            overflow: hidden;
        }

        .contact-info {
            background-color: var(--primary);
            color: var(--white);
            padding: 4rem 3rem;
            display: flex;
            flex-direction: column;
            justify-content: space-between;
        }

        .contact-info h3 {
            color: var(--white);
            font-size: 2rem;
            margin-bottom: 1rem;
        }

        .contact-info p {
            opacity: 0.9;
            margin-bottom: 2.5rem;
        }

        .contact-details {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
            margin-bottom: 3rem;
        }

        .contact-item {
            display: flex;
            align-items: flex-start;
            gap: 1rem;
        }

        .contact-item svg {
            width: 24px;
            height: 24px;
            flex-shrink: 0;
            color: var(--secondary);
        }

        .contact-form {
            padding: 4rem 3rem;
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
        }

        .form-row {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1.5rem;
        }

        .form-group {
            display: flex;
            flex-direction: column;
            gap: 0.5rem;
        }

        .form-group label {
            font-size: 0.85rem;
            font-weight: 600;
            color: var(--neutral-dark);
        }

        .form-group input, .form-group select, .form-group textarea {
            padding: 0.85rem;
            border: 1px solid var(--gray-light);
            border-radius: 8px;
            background-color: var(--neutral-light);
        }

        .form-group textarea {
            resize: vertical;
            min-height: 120px;
        }

        /* =================================================================
           14. FOOTER
           ================================================================ */
        .footer {
            background-color: var(--primary-dark);
            color: var(--white);
            padding: 4rem 0 2rem 0;
        }

        .footer-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
            gap: 3rem;
            margin-bottom: 3rem;
        }

        .footer-col h4 {
            color: var(--white);
            font-size: 1.2rem;
            margin-bottom: 1.5rem;
            position: relative;
        }

        .footer-col h4::after {
            content: '';
            display: block;
            width: 30px;
            height: 2px;
            background-color: var(--secondary);
            margin-top: 0.5rem;
        }

        .footer-links {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .footer-links a {
            color: var(--gray-light);
            opacity: 0.8;
            transition: var(--transition);
        }

        .footer-links a:hover {
            opacity: 1;
            color: var(--secondary);
            transform: translateX(5px);
        }

        .social-links {
            display: flex;
            gap: 1rem;
            margin-top: 1.5rem;
        }

        .social-icon {
            width: 40px;
            height: 40px;
            border-radius: 50%;
            background-color: rgba(255,255,255,0.1);
            display: flex;
            align-items: center;
            justify-content: center;
            transition: var(--transition);
        }

        .social-icon:hover {
            background-color: var(--secondary);
            color: var(--primary-dark);
        }

        .footer-bottom {
            border-top: 1px solid rgba(255,255,255,0.1);
            padding-top: 2rem;
            text-align: center;
            font-size: 0.9rem;
            color: var(--gray);
        }

        /* =================================================================
           15. RESPONSIVE DESIGN (MEDIA QUERIES)
           ================================================================ */
        @media (max-width: 1200px) {
            .container {
                padding: 0 2rem;
            }
        }

        @media (max-width: 900px) {
            .about-content {
                grid-template-columns: 1fr;
                gap: 2rem;
            }

            .stats-grid {
                grid-template-columns: repeat(2, 1fr);
            }

            .contact-wrapper {
                grid-template-columns: 1fr;
            }

            /* Configuration Menu Mobile Burger (CSS Pur) */
            .nav-toggle-label {
                display: flex;
                flex-direction: column;
                justify-content: space-between;
                width: 30px;
                height: 21px;
                cursor: pointer;
                z-index: 1001;
            }

            .nav-toggle-label span {
                display: block;
                height: 3px;
                width: 100%;
                background-color: var(--neutral-dark);
                border-radius: 2px;
                transition: var(--transition);
            }

            .nav-menu {
                position: fixed;
                top: 0;
                right: -100%;
                width: 80%;
                max-width: 400px;
                height: 100vh;
                background-color: var(--white);
                flex-direction: column;
                justify-content: center;
                align-items: center;
                box-shadow: -5px 0 25px rgba(0,0,0,0.1);
                transition: var(--transition);
                z-index: 1000;
            }

            .nav-toggle:checked ~ .nav-menu {
                right: 0;
            }

            /* Animation du burger en croix */
            .nav-toggle:checked ~ .nav-toggle-label span:nth-child(1) {
                transform: translateY(9px) rotate(45deg);
            }
            .nav-toggle:checked ~ .nav-toggle-label span:nth-child(2) {
                opacity: 0;
            }
            .nav-toggle:checked ~ .nav-toggle-label span:nth-child(3) {
                transform: translateY(-9px) rotate(-45deg);
            }
        }

        @media (max-width: 600px) {
            .hero-buttons {
                flex-direction: column;
                width: 100%;
            }

            .hero-buttons .btn {
                width: 100%;
            }

            .search-form {
                grid-template-columns: 1fr;
            }

            .form-row {
                grid-template-columns: 1fr;
            }

            .stats-grid {
                grid-template-columns: 1fr;
            }

            .contact-info, .contact-form {
                padding: 2.5rem 1.5rem;
            }
        }

        /* Accessibilité - Réduction de mouvements */
        @media (prefers-reduced-motion: reduce) {
            html {
                scroll-behavior: auto;
            }
            *, *::before, *::after {
                transition-duration: 0.01ms !important;
                animation-duration: 0.01ms !important;
                animation-iteration-count: 1 !important;
            }
        }
    </style>
</head>
