### 2. Code JavaScript (`script.js`)

Ce script gère l'état complet de la calculatrice (entrée actuelle, opérateur, valeur précédente), le calcul sécurisé sans `eval()`, ainsi que les fonctionnalités spéciales (AC, inversion de signe `+/-`, et pourcentage `%`).

*Note : Ce script s'attend à trouver des boutons dotés d'attributs clairs (ex: `data-number`, `data-action="add"`, etc.) ou gère les classes/textes par défaut.*

```javascript
document.addEventListener('DOMContentLoaded', () => {
    const previousOperandElement = document.querySelector('.previous-operand');
    const currentOperandElement = document.querySelector('.current-operand');
    const keysContainer = document.querySelector('.calculator-keys');

    let currentInput = '0';
    let previousInput = '';
    let operation = null;
    let resetScreen = false;

    // Fonction de mise à jour de l'affichage
    function updateDisplay() {
        currentOperandElement.textContent = currentInput;
        if (operation !== null) {
            previousInputElement = `${previousInput} ${operation}`;
            previousOperandElement.textContent = previousInputElement;
        } else {
            previousOperandElement.textContent = '';
        }
    }

    // Gestion de l'ajout de chiffres
    function appendNumber(number) {
        if (currentInput === '0' || resetScreen) {
            currentInput = number;
            resetScreen = false;
        } else {
            // Empêcher d'ajouter plusieurs points décimaux
            if (number === '.' && currentInput.includes('.')) return;
            currentInput += number;
        }
    }

    // Gestion de la sélection des opérateurs (+, -, *, /)
    function chooseOperation(op) {
        if (currentInput === '') return;
        if (previousInput !== '') {
            calculate();
        }
        operation = op;
        previousInput = currentInput;
        resetScreen = true;
    }

    // Calcul mathématique sécurisé (Sans eval())
    function calculate() {
        let computation;
        const prev = parseFloat(previousInput);
        const current = parseFloat(currentInput);

        if (isNaN(prev) || isNaN(current)) return;

        switch (operation) {
            case '+':
                computation = prev + current;
                break;
            case '-':
                computation = prev - current;
                break;
            case '*':
                computation = prev * current;
                break;
            case '/':
                if (current === 0) {
                    alert("Division par zéro impossible !");
                    clearAll();
                    return;
                }
                computation = prev / current;
                break;
            default:
                return;
        }

        currentInput = roundResult(computation).toString();
        operation = null;
        previousInput = '';
    }

    // Éviter les problèmes d'arrondi des nombres décimaux en JS (ex: 0.1 + 0.2)
    function roundResult(num) {
        return Math.round(num * 100000000) / 100000000;
    }

    // Bouton AC (Tout effacer)
    function clearAll() {
        currentInput = '0';
        previousInput = '';
        operation = null;
        resetScreen = false;
    }

    // Gestion du bouton de changement de signe (+/-)
    function toggleSign() {
        if (currentInput === '0') return;
        currentInput = (parseFloat(currentInput) * -1).toString();
    }

    // Gestion du pourcentage (%)
    function percentage() {
        const current = parseFloat(currentInput);
        if (isNaN(current)) return;
        currentInput = (current / 100).toString();
    }

    // Écouteur d'événements global (Event Delegation sur le conteneur des touches)
    keysContainer.addEventListener('click', (event) => {
        const button = event.target;
        if (!button.matches('button')) return;

        // Si c'est un chiffre ou un point
        if (button.classList.contains('btn-number') || !isNaN(button.textContent) || button.textContent === '.') {
            appendNumber(button.textContent);
        }
        // Si c'est un opérateur
        else if (button.classList.contains('btn-operator')) {
            chooseOperation(button.textContent);
        }
        // Bouton Égal
        else if (button.classList.contains('btn-equal')) {
            calculate();
            resetScreen = true;
        }
        // Bouton AC (Tout effacer)
        else if (button.classList.contains('btn-ac') || button.textContent === 'AC') {
            clearAll();
        }
        // Bouton Changement de signe (+/-)
        else if (button.classList.contains('btn-sign') || button.textContent === '+/-') {
            toggleSign();
        }
        // Bouton Pourcentage (%)
        else if (button.classList.contains('btn-percent') || button.textContent === '%') {
            percentage();
        }

        updateDisplay();
    });

    // Initialisation
    updateDisplay();
});
```

