```javascript
/**
 * Suite de tests unitaires et d'intégration - Agence de Voyage
 * Auteur : Test Agent
 * Stack : Jest, Supertest
 */

const request = require('supertest');
// Note : Pour les tests, on s'assure que server.js exporte 'app'
const express = require('express');

// Importation ou simulation de l'application (ici on suppose que server.js exporte app)
// Pour l'exercice, nous reprenons l'instance de l'API testée.
const app = require('./server'); 

describe('🌍 API Agence de Voyage - Suite de Tests', () => {

    let createdDestinationId;
    let createdBookingId;

    // ==========================================
    // TESTS DU MODULE CATALOGUE DES OFFRES
    // ==========================================
    describe('GET /api/destinations', () => {
        it('Doit retourner la liste de toutes les destinations', async () => {
            const res = await request(app).get('/api/destinations');
            expect(res.statusCode).toEqual(200);
            expect(res.body.success).toBe(true);
            expect(Array.isArray(res.body.data)).toBe(true);
            expect(res.body.count).toBeGreaterThan(0);
        });

        it('Doit filtrer les destinations par type (?type=vol)', async () => {
            const res = await request(app).get('/api/destinations?type=vol');
            expect(res.statusCode).toEqual(200);
            expect(res.body.data.every(d => d.type === 'vol')).toBe(true);
        });
    });

    describe('GET /api/destinations/:id', () => {
        it('Doit retourner une destination valide par son ID', async () => {
            const res = await request(app).get('/api/destinations/dest-1');
            expect(res.statusCode).toEqual(200);
            expect(res.body.success).toBe(true);
            expect(res.body.data.id).toEqual('dest-1');
        });

        it('Doit retourner une erreur 404 si la destination n\'existe pas', async () => {
            const res = await request(app).get('/api/destinations/dest-inexistant');
            expect(res.statusCode).toEqual(404);
            expect(res.body.success).toBe(false);
            expect(res.body.message).toEqual("Offre de voyage non trouvée.");
        });
    });

    describe('POST /api/destinations (Admin)', () => {
        it('Doit créer une nouvelle offre de voyage avec succès', async () => {
            const newOffer = {
                title: "Weekend à Rome",
                type: "circuit",
                price: 450,
                stock: 10,
                location: "Italie"
            };

            const res = await request(app)
                .post('/api/destinations')
                .send(newOffer);

            expect(res.statusCode).toEqual(201);
            expect(res.body.success).toBe(true);
            expect(res.body.data).toHaveProperty('id');
            createdDestinationId = res.body.data.id; // Sauvegarde pour les tests de réservation
        });

        it('Doit échouer si un champ obligatoire est manquant', async () => {
            const incompleteOffer = {
                title: "Weekend raté",
                price: 100
            };

            const res = await request(app)
                .post('/api/destinations')
                .send(incompleteOffer);

            expect(res.statusCode).toEqual(400);
            expect(res.body.success).toBe(false);
        });
    });

    // ==========================================
    // TESTS DU MODULE DE RÉSERVATION & STOCK
    // ==========================================
    describe('POST /api/bookings', () => {
        it('Doit créer une réservation et décrémenter le stock temporairement', async () => {
            const bookingPayload = {
                destinationId: createdDestinationId,
                customerName: "Jean Dupont",
                customerEmail: "jean.dupont@example.com",
                travelersCount: 2
            };

            const res = await request(app)
                .post('/api/bookings')
                .send(bookingPayload);

            expect(res.statusCode).toEqual(201);
            expect(res.body.success).toBe(true);
            expect(res.body.data.status).toEqual("EN_ATTENTE_PAIEMENT");
            expect(res.body.data.travelersCount).toEqual(2);

            createdBookingId = res.body.data.id;
        });

        it('Doit refuser la réservation si le stock est insuffisant (Conflict 409)', async () => {
            const excessiveBookingPayload = {
                destinationId: createdDestinationId,
                customerName: "Marie Curie",
                customerEmail: "marie.curie@example.com",
                travelersCount: 50 // Stock restant : 8 (10 - 2)
            };

            const res = await request(app)
                .post('/api/bookings')
                .send(excessiveBookingPayload);

            expect(res.statusCode).toEqual(409);
            expect(res.body.success).toBe(false);
            expect(res.body.message).toContain("Stock insuffisant");
        });
    });

    describe('GET /api/bookings/:id', () => {
        it('Doit récupérer les détails d\'une réservation existante', async () => {
            const res = await request(app).get(`/api/bookings/${createdBookingId}`);
            expect(res.statusCode).toEqual(200);
            expect(res.body.success).toBe(true);
            expect(res.body.data.id).toEqual(createdBookingId);
        });
    });

    describe('POST /api/bookings/:id/pay', () => {
        it('Doit valider le paiement et confirmer la réservation', async () => {
            const res = await request(app).post(`/api/bookings/${createdBookingId}/pay`);

            expect(res.statusCode).toEqual(200);
            expect(res.body.success).toBe(true);
            expect(res.body.data.status).toEqual("CONFIRME");
            expect(res.body.message).toContain("Réservation confirmée");
        });

        it('Doit refuser de payer une réservation déjà confirmée', async () => {
            const res = await request(app).post(`/api/bookings/${createdBookingId}/pay`);

            expect(res.statusCode).toEqual(400);
            expect(res.body.success).toBe(false);
            expect(res.body.message).toContain("Impossible de payer cette réservation");
        });
    });
});
