        },
        effect: "Rend votre personnage invincible pendant 5 minutes."
    },
    {
        id: "cheat_2",
        title: "Spawn Véhicule Sportif (Cheetah)",
        category: "Véhicule",
        platforms: {
            playstation: ["R2", "Gauche", "L1", "L2", "Droite", "R1"],
            xbox: ["RT", "Gauche", "LB", "LT", "Droite", "RB"],
            pc: ["RAPIDGT"]
        },
        effect: "Fait apparaitre instantanément une voiture de sport haut de gamme."
    },
    {
        id: "cheat_3",
        title: "Niveau de Recherche Maximum (5 Étoiles)",
        category: "Monde",
        platforms: {
            playstation: ["R1", "R1", Rond, "R2", "Gauche", "Droite"],
            xbox: ["RB", "RB", "B", "RT", "Gauche", "Droite"],
            pc: ["FUGITIVE"]
        },
        effect: "Déclenche immédiatement une course-poursuite intense avec la police de Leonida."
    },
    {
        id: "cheat_4",
        title: "Super Saut (Super Jump)",
        category: "Personnage",
        platforms: {
            playstation: ["Gauche", "Gauche", "Triangle", "Triangle", "Droite", "Droite"],
            xbox: ["Gauche", "Gauche", "Y", "Y", "Droite", "Droite"],
            pc: ["HOPTOIT"]
        },
        effect: "Permet à Lucia ou Jason de sauter dix fois plus haut que la normale."
    }
];

function renderCheats(filter = "all", search = "") {
    const grid = document.getElementById("cheatsGrid");
    grid.innerHTML = "";

    const filtered = cheatsData.filter(cheat => {
        const matchesSearch = cheat.title.toLowerCase().includes(search.toLowerCase()) || cheat.effect.toLowerCase().includes(search.toLowerCase());
        const matchesPlatform = filter === "all" || cheat.platforms[filter];
        return matchesSearch && matchesPlatform;
    });

    if (filtered.length === 0) {
        grid.innerHTML = `<p class="col-span-full text-center text-gray-500 py-8">Aucun code de triche trouvé.</p>`;
        return;
    }

    filtered.forEach(cheat => {
        let platformHTML = "";
        for (const [plat, codes] of Object.entries(cheat.platforms)) {
            platformHTML += `<div class="mb-2"><span class="text-xs uppercase font-mono text-gtaCyan">${plat}:</span> <span class="bg-gtaDark px-2 py-1 rounded text-sm font-mono border border-gray-800">${codes.join(" + ")}</span></div>`;
        }

        const card = document.createElement("div");
        card.className = "bg-gtaCard p-6 rounded-2xl border border-gray-800 hover:border-gtaMagenta/50 transition shadow-xl flex flex-col justify-between";
        card.innerHTML = `
            <div>
                <span class="text-xs uppercase px-2 py-1 bg-gtaOrange/10 text-gtaOrange rounded border border-gtaOrange/30 font-mono">${cheat.category}</span>
                <h3 class="text-xl font-bold mt-3 mb-2">${cheat.title}</h3>
                <p class="text-gray-400 text-sm mb-4">${cheat.effect}</p>
            </div>
            <div class="border-t border-gray-800 pt-4 mt-2">
                ${platformHTML}
            </div>
        `;
        grid.appendChild(card);
    });
}

// Écouteurs d'événements pour les filtres et la recherche
document.addEventListener("DOMContentLoaded", () => {
    renderCheats();

    document.querySelectorAll(".platform-btn").forEach(btn => {
        btn.addEventListener("click", (e) => {
            document.querySelectorAll(".platform-btn").forEach(b => b.classList.replace("bg-gtaMagenta", "bg-gtaCard"));
            e.target.classList.replace("bg-gtaCard", "bg-gtaMagenta");
            const platform = e.target.getAttribute("data-platform");
            const searchVal = document.getElementById("searchCheat").value;
            renderCheats(platform, searchVal);
        });
    });

    document.getElementById("searchCheat").addEventListener("input", (e) => {
        const activePlatform = document.querySelector(".platform-btn.bg-gtaMagenta").getAttribute("data-platform");
        renderCheats(activePlatform, e.target.value);
    });
});
