## 4. Module de Carte Interactive (`js/map.js`)
Intégration de Leaflet.js configuré pour afficher les points d'intérêt de Vice City / Leonida avec filtrage dynamique par catégories.

```javascript
let map;
let markers = [];

const mapLocations = [
    { name: "Planque Principale de Lucia", category: "safehouse", lat: 25.7617, lng: -80.1918, desc: "Appartement sécurisé situé dans les quartiers sud de Vice City." },
    { name: "Ammu-Nation Vice Beach", category: "weapon", lat: 25.7800, lng: -80.1300, desc: "Achetez des armes à feu et des gilets pare-balles." },
    { name: "Easter Egg : OvNI de Vice City", category: "easteregg", lat: 25.8500, lng: -80.2500, desc: "Lieu mystérieux où des phénomènes étranges se produisent la nuit." }
];

function initMap() {
    map = L.map('interactiveMap', {
        center: [25.7617, -80.1918],
        zoom: 12,
        zoomControl: false
    });

    // Tuiles de carte stylisées style sombre
    L.tileLayer('https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png', {
        attribution: '&copy; OpenStreetMap & CARTO',
        maxZoom: 19
    }).addTo(map);

    // Ajouter le contrôle du zoom en haut à droite
    L.control.zoom({ position: 'topright' }).addTo(map);

    updateMarkers();

    // Écouteurs pour les filtres de cartes
    document.querySelectorAll('.map-filter').forEach(checkbox => {
        checkbox.addEventListener('change', updateMarkers);
    });
}

function updateMarkers() {
    // Supprimer les anciens marqueurs
    markers.forEach(m => map.removeLayer(m));
    markers = [];

    const activeCategories = Array.from(document.querySelectorAll('.map-filter:checked'))
        .map(cb => cb.getAttribute('data-category'));

    mapLocations.forEach(loc => {
        if (activeCategories.includes(loc.category)) {
            const marker = L.marker([loc.lat, loc.lng]).addTo(map);
            marker.bindPopup(`
                <div class="p-2">
                    <h4 class="font-bold text-gtaMagenta text-base">${loc.name}</h4>
                    <p class="text-sm text-gray-300 mt-1">${loc.desc}</p>
                </div>
            `);
            markers.push(marker);
        }
    });
}

document.addEventListener("DOMContentLoaded", () => {
    initMap();
});
```

