function renderCheats(filter = "all", searchQuery = "") {
    const container = document.getElementById("cheatsContainer");
    container.innerHTML = "";

    const filtered = cheatsData.filter(cheat => {
        const matchesCategory = filter === "all" || cheat.category === filter;
        const matchesSearch = cheat.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                              cheat.description.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesCategory && matchesSearch;
    });

    if (filtered.length === 0) {
        container.innerHTML = `<p style="grid-column: 1/-1; text-align:center; color: var(--neon-pink);">Aucun code de triche trouvé.</p>`;
        return;
    }

    filtered.forEach(cheat => {
        const card = document.createElement("div");
        card.className = "cheat-card";
        card.innerHTML = `
            <h4><i class="fa-solid ${cheat.icon}" style="color: var(--neon-cyan);"></i> ${cheat.title}</h4>
            <p>${cheat.description}</p>
            <div class="platform-code">
                <span><strong>PS5:</strong> ${cheat.platforms.ps5}</span>
                <button class="copy-btn" onclick="copyToClipboard('${cheat.platforms.ps5}')">Copier</button>
            </div>
            <div class="platform-code">
                <span><strong>Xbox:</strong> ${cheat.platforms.xbox}</span>
                <button class="copy-btn" onclick="copyToClipboard('${cheat.platforms.xbox}')">Copier</button>
            </div>
        `;
        container.appendChild(card);
    });
}

function copyToClipboard(text) {
    navigator.clipboard.writeText(text).then(() => {
        alert("Code copié dans le presse-papier !");
    });
}
