                <!-- Généré dynamiquement par JavaScript -->
            </div>
        </div>
    </section>

    <!-- Section Map Interactive -->
    <section id="map">
        <h2 class="section-title">MAP INTERACTIVE DE VICE CITY</h2>
        <p class="section-subtitle">Trouvez tous les points d'intérêts, easter eggs et collectibles de Leonida.</p>

        <div class="map-wrapper">
            <div class="map-toolbar">
                <button class="map-filter-btn active" onclick="filterMarkers('all')">Tous les POI</button>
                <button class="map-filter-btn" onclick="filterMarkers('collectible')">Collectibles</button>
                <button class="map-filter-btn" onclick="filterMarkers('weapon')">Armes Rares</button>
                <button class="map-filter-btn" onclick="filterMarkers('easteregg')">Easter Eggs</button>
            </div>
            <div id="map-container"></div>
        </div>
    </section>

    <!-- Footer -->
    <footer>
        <p>&copy; 2026 GTA VI Fan Concept - Développé par Developer Agent. Tous droits réservés (C'est un projet fictif).</p>
    </footer>

    <!-- Leaflet JS pour la map -->
    <script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script>

    <script>
        /* --- 1. GESTION DES CODES DE TRICHE --- */
        const cheatsData = [
            { title: "Invincibilité (5 minutes)", category: "Joueur", code: "PAIN-KILLER" },
            { title: "Santé et Gilet Max", category: "Joueur", code: "TURTLE" },
            { title: "Toutes les Armes", category: "Armes", code: "TOOL-UP" },
            { title: "Augmenter l'indice de recherche", category: "Joueur", code: "FUGITIVE" },
            { title: "Diminuer l'indice de recherche", category: "Joueur", code: "LAWYER-UP" },
            { title: "Mode Alcoolisé", category: "Joueur", code: "LIQUOR" },
            { title: "Gravité Lunaire", category: "Monde", code: "HOP-TO-IT" },
            { title: "Changer la météo (Tempête)", category: "Monde", code: "MAKE-IT-RAIN" },
            { title: "Voiture de Sport Spawn (Cheetah)", category: "Armes", code: "PARADISE" }
        ];

        const cheatsGrid = document.getElementById('cheatsGrid');
        const searchInput = document.getElementById('searchInput');

        function renderCheats(data) {
            cheatsGrid.innerHTML = '';
            if (data.length === 0) {
                cheatsGrid.innerHTML = '<p style="grid-column: 1/-1; text-align: center; color: var(--text-muted);">Aucun code trouvé.</p>';
                return;
            }
            data.forEach(cheat => {
                const card = document.createElement('div');
                card.classList.add('cheat-card');
                card.innerHTML = `
                    <div class="cheat-category">${cheat.category}</div>
                    <div class="cheat-title">${cheat.title}</div>
                    <div class="cheat-code">${cheat.code}</div>
                `;
                cheatsGrid.appendChild(card);
            });
        }

        function filterCheats(category) {
            document.querySelectorAll('.filter-btn').forEach(btn => btn.classList.remove('active'));
            event.target.classList.add('active');

            if (category === 'all') {
                renderCheats(cheatsData);
            } else {
                const filtered = cheatsData.filter(c => c.category === category);
                renderCheats(filtered);
            }
        }

        searchInput.addEventListener('input', (e) => {
            const query = e.target.value.toLowerCase();
            const filtered = cheatsData.filter(c => 
                c.title.toLowerCase().includes(query) || 
                c.code.toLowerCase().includes(query) ||
                c.category.toLowerCase().includes(query)
            );
            renderCheats(filtered);
        });

        // Initialisation de l'affichage des cheats
        renderCheats(cheatsData);


        /* --- 2. GESTION DE LA MAP INTERACTIVE (LEAFLET.JS) --- */
        // Initialisation de la map en coordonnées simples (idéal pour les cartes de jeux vidéo)
        const map = L.map('map-container', {
            crs: L.CRS.Simple,
            minZoom: 1,
            maxZoom: 4,
            zoomControl: true
        });

        // Dimensions virtuelles de la map de Vice City
        const bounds = [[0, 0], [1000, 1000]];
        // Image de fond factice ou tuiles (ici fond uni sombre stylisé pour l'exemple si pas d'image de map tuilée)
        map.fitBounds(bounds);

        // Données des Points d'Intérêt (POI) avec leurs types et coordonnées sur la grille
        const poiData = [
            { id: 1, type: 'collectible', title: 'Paquet Caché #1', coords: [300, 400], desc: 'Situé derrière le motel abandonné de Vice Beach.' },
            { id: 2, type: 'collectible', title: 'Paquet Caché #2', coords: [700, 200], desc: 'Sur le toit du parking à étages.' },
            { id: 3, type: 'weapon', title: 'Minigun Secret', coords: [500, 800], desc: 'Dans la zone militaire fermée.' },
            { id: 4, type: 'easteregg', title: 'Référence Alligator Géant', coords: [200, 750], desc: 'Dans les marécages de Leonida.' }
        ];

        let markersLayer = L.layerGroup().addTo(map);

        function renderMarkers(filterType) {
            markersLayer.clearLayers();

            poiData.forEach(poi => {
                if (filterType === 'all' || poi.type === filterType) {
                    // Création d'un marqueur personnalisé aux couleurs néon
                    let markerColor = '#00d2ff';
                    if (poi.type === 'collectible') markerColor = '#ff2a85';
                    if (poi.type === 'easteregg') markerColor = '#9a00ff';

                    const customIcon = L.divIcon({
                        className: 'custom-div-icon',
                        html: `<div style="background-color: ${markerColor}; width: 16px; height: 16px; border-radius: 50%; border: 2px solid white; box-shadow: 0 0 10px ${markerColor};"></div>`,
                        iconSize: [16, 16],
                        iconAnchor: [8, 8]
                    });

                    const marker = L.marker(poi.coords, { icon: customIcon })
                        .bindPopup(`<b style="color: #0b0914;">${poi.title}</b><br><span style="color: #333;">${poi.desc}</span>`);

                    markersLayer.addLayer(marker);
                }
            });
        }

        function filterMarkers(type) {
            document.querySelectorAll('.map-filter-btn').forEach(btn => btn.classList.remove('active'));
            event.target.classList.add('active');
            renderMarkers(type);
        }

        // Afficher tous les marqueurs au chargement
        renderMarkers('all');
    </script>
</body>
</html>
```

