        <header class="bg-blue-600 text-white shadow-md py-4 px-6 flex justify-between items-center">
            <h1 class="text-2xl font-bold flex items-center gap-2">
                <i class="fa-solid fa-calendar-days"></i> Cal App
            </h1>
            <p id="current-date-header" class="text-sm bg-blue-700 px-3 py-1 rounded-full"></p>
        </header>

        <!-- Contenu Principal -->
        <main class="flex-1 max-w-7xl w-full mx-auto p-4 md:p-6 grid grid-cols-1 lg:grid-cols-3 gap-6">

            <!-- Section Calendrier (2 colonnes sur grand écran) -->
            <div class="lg:col-span-2 bg-white rounded-xl shadow-md p-6 flex flex-col">
