                        <button onclick="goToToday()" class="px-4 py-2 rounded-lg bg-blue-50 text-blue-600 font-medium hover:bg-blue-100 transition">
                            Aujourd'hui
                        </button>
                        <button onclick="changeMonth(1)" class="p-2 rounded-lg bg-gray-100 hover:bg-gray-200 text-gray-700 transition">
                            <i class="fa-solid fa-chevron-right"></i>
                        </button>
                    </div>
                </div>

                <!-- Jours de la semaine -->
                <div class="grid grid-cols-7 gap-2 text-center font-bold text-gray-500 text-sm mb-2">
                    <div>Lun</div><div>Mar</div><div>Mer</div><div>Jeu</div><div>Ven</div><div>Sam</div><div>Dim</div>
                </div>

                <!-- Grille des jours du mois -->
                <div id="calendar-grid" class="grid grid-cols-7 gap-2 flex-1 auto-rows-fr">
                    <!-- Généré dynamiquement par JavaScript -->
                </div>
            </div>

            <!-- Section Gestion des Événements / Tâches (1 colonne) -->
            <div class="bg-white rounded-xl shadow-md p-6 flex flex-col">
                <h3 id="selected-date-title" class="text-lg font-semibold text-gray-800 mb-4 pb-2 border-b">
                    Sélectionnez une date
                </h3>

                <!-- Formulaire d'ajout / modification -->
                <form id="event-form" onsubmit="handleFormSubmit(event)" class="space-y-4 mb-6">
                    <input type="hidden" id="event-id">
                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-1">Titre de l'événement</label>
                        <input type="text" id="event-title" required placeholder="Ex: Réunion d'équipe" 
                            class="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500">
                    </div>
                    <div>
                        <label class="block text-sm font-medium text-gray-700 mb-1">Heure (Optionnel)</label>
