### 控制器 3. Contrôleur : `src/controllers/taskController.js`

Contient la logique pour chaque opération CRUD (Create, Read, Update, Delete) avec une gestion rigoureuse des erreurs.

```javascript
const db = require('../config/database');

// Récupérer toutes les tâches
exports.getAllTasks = (req, res) => {
    const query = 'SELECT * FROM tasks ORDER BY created_at DESC';
    db.all(query, [], (err, rows) => {
        if (err) {
            return res.status(500).json({ error: 'Erreur serveur interne', details: err.message });
        }
        res.status(200).json({
            success: true,
            count: rows.length,
            data: rows
        });
    });
};

// Récupérer une tâche par son ID
exports.getTaskById = (req, res) => {
    const { id } = req.params;
    const query = 'SELECT * FROM tasks WHERE id = ?';

    db.get(query, [id], (err, row) => {
        if (err) {
            return res.status(500).json({ error: 'Erreur serveur interne', details: err.message });
        }
        if (!row) {
            return res.status(404).json({ error: `Tâche avec l'ID ${id} non trouvée.` });
        }
        res.status(200).json({ success: true, data: row });
    });
};

// Créer une nouvelle tâche
exports.createTask = (req, res) => {
    const { title, description } = req.body;

    // Validation basique des données entrantes
    if (!title || title.trim() === '') {
        return res.status(400).json({ error: 'Le champ "title" est obligatoire et ne peut être vide.' });
    }

    const query = 'INSERT INTO tasks (title, description, completed) VALUES (?, ?, 0)';
    db.run(query, [title, description || ''], function(err) {
        if (err) {
            return res.status(500).json({ error: 'Erreur lors de la création de la tâche', details: err.message });
        }

        // Retourner la tâche créée avec son ID généré
        res.status(201).json({
            success: true,
            message: 'Tâche créée avec succès.',
            data: {
                id: this.lastID,
                title,
                description: description || '',
                completed: 0
            }
        });
    });
};

// Mettre à jour une tâche existante
exports.updateTask = (req, res) => {
    const { id } = req.params;
    const { title, description, completed } = req.body;

    // Vérifier d'abord si la tâche existe
    const checkQuery = 'SELECT * FROM tasks WHERE id = ?';
    db.get(checkQuery, [id], (err, row) => {
        if (err) return res.status(500).json({ error: err.message });
        if (!row) return res.status(404).json({ error: `Tâche avec l'ID ${id} non trouvée.` });

        // Conserver les anciennes valeurs si elles ne sont pas fournies dans la requête
        const updatedTitle = title !== undefined ? title : row.title;
        const updatedDescription = description !== undefined ? description : row.description;
        const updatedCompleted = completed !== undefined ? (completed ? 1 : 0) : row.completed;

        const updateQuery = 'UPDATE tasks SET title = ?, description = ?, completed = ? WHERE id = ?';
        db.run(updateQuery, [updatedTitle, updatedDescription, updatedCompleted, id], function(err) {
            if (err) {
                return res.status(500).json({ error: 'Erreur lors de la mise à jour', details: err.message });
            }
            res.status(200).json({
                success: true,
                message: 'Tâche mise à jour avec succès.',
                data: {
                    id: Number(id),
                    title: updatedTitle,
                    description: updatedDescription,
                    completed: updatedCompleted
                }
            });
        });
    });
};

// Supprimer une tâche
exports.deleteTask = (req, res) => {
    const { id } = req.params;
    const query = 'DELETE FROM tasks WHERE id = ?';

    db.run(query, [id], function(err) {
        if (err) {
            return res.status(500).json({ error: 'Erreur lors de la suppression', details: err.message });
        }
        if (this.changes === 0) {
            return res.status(404).json({ error: `Tâche avec l'ID ${id} non trouvée.` });
        }
        res.status(200).json({
            success: true,
            message: `Tâche avec l'ID ${id} supprimée avec succès.`
        });
    });
};
