### 3. `script.js` (Interactions & Animations)

```javascript
document.addEventListener('DOMContentLoaded', () => {

    // --- 1. Header scroll effect ---
    const header = document.getElementById('header');

    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    });

    // --- 2. Mobile Menu Toggle ---
    const burger = document.getElementById('burger');
    const navMenu = document.getElementById('navMenu');
    const navLinks = document.querySelectorAll('.nav-link');

    burger.addEventListener('click', () => {
        navMenu.classList.toggle('active');
        // Animation simple du burger (optionnelle)
        burger.classList.toggle('toggle');
    });

    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            navMenu.classList.remove('active');
        });
    });

    // --- 3. Destination Filtering System ---
    const filterBtns = document.querySelectorAll('.filter-btn');
    const destinationCards = document.querySelectorAll('.destination-card');

    filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            // Retirer la classe active de tous les boutons
            filterBtns.forEach(b => b.classList.remove('active'));
            // Ajouter la classe active au bouton cliqué
            btn.classList.add('active');

            const filterValue = btn.getAttribute('data-filter');

            destinationCards.forEach(card => {
                const category = card.getAttribute('data-category');

                if (filterValue === 'all' || category === filterValue) {
                    card.style.display = 'block';
                    setTimeout(() => {
                        card.style.opacity = '1';
                        card.style.transform = 'translateY(0)';
                    }, 50);
                } else {
                    card.style.opacity = '0';
                    card.style.transform = 'translateY(20px)';
                    setTimeout(() => {
                        card.style.display = 'none';
                    }, 300);
                }
            });
        });
    });

    // --- 4. Interactive Form Submission ---
    const bookingForm = document.getElementById('bookingForm');
    const formSuccess = document.getElementById('formSuccess');

    if (bookingForm) {
        bookingForm.addEventListener('submit', (e) => {
            e.preventDefault();

            // Simulation d'envoi de données (Effet visuel luxueux)
            bookingForm.style.opacity = '0';
            setTimeout(() => {
                bookingForm.classList.add('hidden');
                formSuccess.classList.remove('hidden');
                formSuccess.style.opacity = '0';

                // Fade-in du message de succès
                let opacity = 0;
                const fadeIn = setInterval(() => {
                    if (opacity < 1) {
                        opacity += 0.1;
                        formSuccess.style.opacity = opacity;
                    } else {
                        clearInterval(fadeIn);
                    }
                }, 50);
            }, 400);
        });
    }

    // --- 5. Simple Scroll Reveal Animation ---
    const observerOptions = {
        threshold: 0.1
    };

    const observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.opacity = '1';
                entry.target.style.transform = 'translateY(0)';
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Appliquer l'effet d'apparition sur les sections principales
    document.querySelectorAll('.destination-card, .exp-grid, .contact-form').forEach(el => {
        el.style.opacity = '0';
        el.style.transform = 'translateY(30px)';
        el.style.transition = 'all 0.8s cubic-bezier(0.16, 1, 0.3, 1)';
        observer.observe(el);
    });
});
```

