### 3. `script.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {

    /* --- 1. MENU MOBILE TOGGLE --- */
    const mobileMenuToggle = document.getElementById('mobile-menu');
    const navUl = document.querySelector('nav ul');

    mobileMenuToggle.addEventListener('click', () => {
        navUl.classList.toggle('show');
    });

    // Fermer le menu au clic sur un lien
    document.querySelectorAll('nav a').forEach(link => {
        link.addEventListener('click', () => {
            navUl.classList.remove('show');
        });
    });


    /* --- 2. SYSTÈME DE RECHERCHE ET FILTRAGE DES CHEATS --- */
    const searchInput = document.getElementById('searchInput');
    const filterButtons = document.querySelectorAll('.filter-btn');
    const cheatRows = document.querySelectorAll('#cheatTable tbody tr');

    let currentFilter = 'all';

    // Fonction de filtrage globale
    function filterCheats() {
        const searchTerm = searchInput.value.toLowerCase().trim();

        cheatRows.forEach(row => {
            const category = row.getAttribute('data-category');
            const textContent = row.textContent.toLowerCase();

            // Vérifie le filtre de catégorie et la recherche textuelle
            const matchesCategory = (currentFilter === 'all' || category === currentFilter);
            const matchesSearch = textContent.includes(searchTerm);

            if (matchesCategory && matchesSearch) {
                row.style.display = '';
            } else {
                row.style.display = 'none';
            }
        });
    }

    // Écouteur pour la barre de recherche
    searchInput.addEventListener('input', filterCheats);

    // Écouteurs pour les boutons de filtres par catégorie
    filterButtons.forEach(btn => {
        btn.addEventListener('click', (e) => {
            // Retirer la classe active de tous les boutons
            filterButtons.forEach(b => b.classList.remove('active'));
            // Ajouter la classe active au bouton cliqué
            e.target.classList.add('active');

            currentFilter = e.target.getAttribute('data-filter');
            filterCheats();
        });
    });


    /* --- 3. MAP INTERACTIVE SIMULÉE --- */
    const markers = document.querySelectorAll('.map-marker');
    const mapInfoPanel = document.getElementById('mapInfoPanel');

    markers.forEach(marker => {
        marker.addEventListener('click', () => {
            const title = marker.getAttribute('data-title');
            const desc = marker.getAttribute('data-desc');

            // Animation visuelle de sélection
            markers.forEach(m => m.style.color = 'var(--neon-magenta)');
            marker.style.color = 'var(--neon-cyan)';

            // Mise à jour du panneau d'information avec un effet fondu subtil
            mapInfoPanel.style.opacity = '0';
            setTimeout(() => {
                mapInfoPanel.innerHTML = `
                    <h3>${title}</h3>
                    <p>${desc}</p>
                `;
                mapInfoPanel.style.opacity = '1';
            }, 150);
        });
    });

    // Style dynamique pour la transition de l'opacité du panneau map
    mapInfoPanel.style.transition = 'opacity 0.2s ease-in-out';
});
```

