```javascript
/**
 * Developer Agent - GTA 6 Application Logic
 * Modular script handling interactivity, cheats, dynamic news, and map controls.
 */

document.addEventListener('DOMContentLoaded', () => {

    // --- 1. NAVIGATION ACTIVE LINK HIGHLIGHTER ---
    const sections = document.querySelectorAll('.gta-section');
    const navLinks = document.querySelectorAll('.nav-link');

    window.addEventListener('scroll', () => {
        let current = '';
        sections.forEach(section => {
            const sectionTop = section.offsetTop;
            const sectionHeight = section.clientHeight;
            if (window.scrollY >= (sectionTop - 200)) {
                current = section.getAttribute('id');
            }
        });

        navLinks.forEach(link => {
            link.classList.remove('active');
            if (link.getAttribute('href').includes(current)) {
                link.classList.add('active');
            }
        });
    });


    // --- 2. SECTION 'CODES DE RICHES' (TABLEAU & RECHERCHE) ---
    const cheatsData = [
        { effect: "Invincibilité (Mode God)", code: "PAIN-KILLER", shortcut: "1-999-724-654" },
        { effect: "Santé et Gilet par balles max", code: "TURTLE", shortcut: "1-999-887-853" },
        { effect: "Armes et Munitions", code: "TOOL-UP", shortcut: "1-999-866-587" },
        { effect: "Niveau de recherche (Recherché +)", code: "FUGITIVE", shortcut: "1-999-3844-8483" },
        { effect: "Niveau de recherche (Baisser)", code: "LAWYER-UP", shortcut: "1-999-5299-3787" },
        { effect: "Mode Ivrogne", code: "LIQUOR", shortcut: "1-999-547-861" },
        { effect: "Course Rapide", code: "CATCH-ME", shortcut: "1-999-228-8463" },
        { effect: "Spawn d'une Supersportive", code: "VAPID", shortcut: "1-999-827-437" }
    ];

    const cheatTableBody = document.getElementById('cheatTableBody');
    const cheatSearchInput = document.getElementById('cheatSearchInput');

    function renderCheats(data) {
        cheatTableBody.innerHTML = '';
        if (data.length === 0) {
            cheatTableBody.innerHTML = `<tr><td colspan="3" style="text-align: center;">Aucun code trouvé</td></tr>`;
            return;
        }
        data.forEach(cheat => {
            const row = document.createElement('tr');
            row.innerHTML = `
                <td>${cheat.effect}</td>
                <td><code>${cheat.code}</code> (${cheat.shortcut})</td>
                <td><button class="btn-copy" data-code="${cheat.shortcut}">Copier</button></td>
            `;
            cheatTableBody.appendChild(row);
        });

        // Ajouter l'événement de copie
        document.querySelectorAll('.btn-copy').forEach(button => {
            button.addEventListener('click', (e) => {
                const codeToCopy = e.target.getAttribute('data-code');
                navigator.clipboard.writeText(codeToCopy).then(() => {
                    e.target.textContent = 'Copié !';
                    setTimeout(() => { e.target.textContent = 'Copier'; }, 2000);
                });
            });
        });
    }

    renderCheats(cheatsData);

    cheatSearchInput.addEventListener('input', (e) => {
        const searchTerm = e.target.value.toLowerCase();
        const filtered = cheatsData.filter(cheat => 
            cheat.effect.toLowerCase().includes(searchTerm) || 
            cheat.code.toLowerCase().includes(searchTerm)
        );
        renderCheats(filtered);
    });


    // --- 3. SECTION 'TOUTES LES INFOS DISPO' (ACTUALITÉS DYNAMIQUES) ---
    const newsData = [
        { date: "14 Mai 2026", title: "Moteur Physique RAGE 9", desc: "Rockstar confirme des avancées majeures sur la simulation de l'eau, le trafic dense et les comportements de la faune sauvage à Leonida.", link: "#" },
        { date: "02 Avril 2026", title: "Intérieurs de Bâtiments", desc: "Selon les dernières fuites analysées, environ 70% des commerces et lieux de service posséderont un intérieur accessible sans temps de chargement.", link: "#" },
        { date: "18 Mars 2026", title: "Économie et Cryptomonnaies", desc: "Le marché boursier virtuel fait son grand retour avec l'intégration d'un système de spéculation immobilière avancé dans Vice City.", link: "#" }
    ];

    const newsGrid = document.getElementById('newsGrid');
    newsData.forEach(item => {
        const card = document.createElement('div');
        card.className = 'news-card';
        card.innerHTML = `
            <div>
                <span class="news-date">${item.date}</span>
                <h3>${item.title}</h3>
                <p>${item.desc}</p>
            </div>
            <a href="${item.link}" class="news-link">Lire la suite &rarr;</a>
        `;
        newsGrid.appendChild(card);
    });


    // --- 4. MAP INTERACTIVE (FONCTIONNALITÉS DE ZOOM & MARQUEURS) ---
    const mapImg = document.getElementById('gtaMapImg');
    const zoomInBtn = document.getElementById('zoomIn');
    const zoomOutBtn = document.getElementById('zoomOut');
    const resetMapBtn = document.getElementById('resetMap');
    const markers = document.querySelectorAll('.map-marker');
    const markerPopup = document.getElementById('markerPopup');
    const popupTitle = document.getElementById('popupTitle');
    const popupDesc = document.getElementById('popupDesc');
    const closePopupBtn = document.getElementById('closePopup');

    let currentZoom = 1;

    zoomInBtn.addEventListener('click', () => {
        if (currentZoom < 2.5) {
            currentZoom += 0.3;
            mapImg.style.transform = `scale(${currentZoom})`;
        }
    });

    zoomOutBtn.addEventListener('click', () => {
        if (currentZoom > 1) {
            currentZoom -= 0.3;
            mapImg.style.transform = `scale(${currentZoom})`;
        }
    });

    resetMapBtn.addEventListener('click', () => {
        currentZoom = 1;
        mapImg.style.transform = `scale(1)`;
        markerPopup.style.display = 'none';
    });

    // Gestion des marqueurs interactifs
    markers.forEach(marker => {
        marker.addEventListener('click', (e) => {
            e.stopPropagation();
            const title = marker.getAttribute('data-title');
            const desc = marker.getAttribute('data-desc');

            popupTitle.textContent = title;
            popupDesc.textContent = desc;
            markerPopup.style.display = 'block';
        });
    });

    closePopupBtn.addEventListener('click', () => {
        markerPopup.style.display = 'none';
    });

    // Fermer le popup en cliquant ailleurs sur la map
    document.getElementById('mapViewport').addEventListener('click', () => {
        markerPopup.style.display = 'none';
    });

});
