document.addEventListener('DOMContentLoaded', () => {
    // 1. Mobile Navigation Toggle
    const burgerMenu = document.getElementById('burgerMenu');
    const nav = document.querySelector('.nav');

    if (burgerMenu && nav) {
        burgerMenu.addEventListener('click', () => {
            nav.classList.toggle('active');
            burgerMenu.classList.toggle('active');
        });
    }

    // 2. Render Home Highlights (3 featured items)
    const homeGrid = document.getElementById('homeHighlightsGrid');
    if (homeGrid) {
        const featured = voyagesData.slice(0, 3);
        homeGrid.innerHTML = featured.map(v => createVoyageCardHTML(v)).join('');
        initCardTriggers();
    }

    // 3. Render Catalog Grid (All 20 items)
    const catalogGrid = document.getElementById('catalogGrid');
    if (catalogGrid) {
        renderCatalog(voyagesData);
        initFilters();
    }

    // 4. Contact Form Handler (Home)
    const contactForm = document.getElementById('contactForm');
    if (contactForm) {
        contactForm.addEventListener('submit', (e) => {
            e.preventDefault();
            showToast("Votre demande a été transmise avec succès. Un concierge vous contactera sous 2 heures.");
            contactForm.reset();
        });
    }

    // 5. Modal Logic
    initModal();
});

// Helper to generate Card HTML
function createVoyageCardHTML(voyage) {
    return `
        <article class="voyage-card">
            <div class="voyage-img-wrapper">
                <img src="${voyage.image}" alt="${voyage.title}" loading="lazy">
                <span class="voyage-badge">${voyage.badge}</span>
            </div>
            <div class="voyage-info">
                <span class="voyage-location">${voyage.location} (${voyage.continent})</span>
                <h3>${voyage.title}</h3>
                <p class="voyage-desc">${voyage.description}</p>
                <div class="voyage-footer">
                    <div class="voyage-price">${voyage.price.toLocaleString()} € <span>/ personne</span></div>
                    <button class="btn btn-outline open-modal-btn" data-id="${voyage.id}">Découvrir</button>
                </div>
            </div>
        </article>
    `;
}

// Render Catalog list
function renderCatalog(data) {
    const catalogGrid = document.getElementById('catalogGrid');
    if (!catalogGrid) return;

    if (data.length === 0) {
        catalogGrid.innerHTML = `<p style="grid-column: 1/-1; text-align: center; padding: 4rem 0; color: var(--text-muted);">Aucun voyage ne correspond à vos critères d'exigence.</p>`;
        return;
    }

    catalogGrid.innerHTML = data.map(v => createVoyageCardHTML(v)).join('');
    initCardTriggers();
}

// Initialize Filters logic
function initFilters() {
    const searchInput = document.getElementById('searchInput');
    const continentFilter = document.getElementById('continentFilter');
    const sortPrice = document.getElementById('sortPrice');

    const filterAndSort = () => {
        let filtered = [...voyagesData];

        // Search text
        const query = searchInput.value.toLowerCase().trim();
        if (query) {
            filtered = filtered.filter(v => 
                v.title.toLowerCase().includes(query) || 
                v.location.toLowerCase().includes(query) ||
                v.description.toLowerCase().includes(query)
            );
        }

        // Continent
        const continent = continentFilter.value;
        if (continent) {
            filtered = filtered.filter(v => v.continent === continent);
        }

        // Sort Price
        const sort = sortPrice.value;
        if (sort === 'asc') {
            filtered.sort((a, b) => a.price - b.price);
        } else if (sort === 'desc') {
            filtered.sort((a, b) => b.price - a.price);
        }

        renderCatalog(filtered);
    };

    if (searchInput) searchInput.addEventListener('input', filterAndSort);
    if (continentFilter) continentFilter.addEventListener('change', filterAndSort);
    if (sortPrice) sortPrice.addEventListener('change', filterAndSort);
}

// Modal & Tunnel de vente simulation
function initModal() {
    const modal = document.getElementById('voyageModal');
    const modalClose = document.getElementById('modalClose');

    if (!modal) return;

    modalClose.addEventListener('click', () => {
        modal.classList.remove('active');
    });

    modal.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.classList.remove('active');
        }
    });
}

function initCardTriggers() {
    const buttons = document.querySelectorAll('.open-modal-btn');
    const modal = document.getElementById('voyageModal');
    const modalBody = document.getElementById('modalBody');

    buttons.forEach(btn => {
        btn.addEventListener('click', () => {
            const id = parseInt(btn.getAttribute('data-id'));
            const voyage = voyagesData.find(v => v.id === id);

            if (voyage && modal && modalBody) {
                modalBody.innerHTML = `
                    <div class="modal-details">
                        <img src="${voyage.image}" alt="${voyage.title}">
                        <span class="subtitle">${voyage.location} (${voyage.continent})</span>
                        <h2>${voyage.title}</h2>
                        <div class="modal-meta">
                            <span class="voyage-price">${voyage.price.toLocaleString()} € <span>/ pers. (${voyage.duration})</span></span>
                            <span class="voyage-badge" style="position:static;">${voyage.badge}</span>
                        </div>
                        <p>${voyage.description}</p>

                        <div style="background: var(--bg-light); padding: 2rem; border: 1px solid var(--border-color); margin-top: 2rem;">
                            <h3 style="font-size: 1.3rem; margin-bottom: 1rem;">Simulation de Réservation Sur-Mesure</h3>
                            <form id="bookingTunnelForm" class="booking-form">
                                <div class="form-group">
                                    <label>Nom & Prénom</label>
                                    <input type="text" required placeholder="Votre nom">
                                </div>
                                <div class="form-group">
                                    <label>Email de contact</label>
                                    <input type="email" required placeholder="votre@email.com">
                                </div>
                                <div class="form-group">
                                    <label>Date souhaitée de départ</label>
                                    <input type="date" required>
                                </div>
                                <button type="submit" class="btn btn-primary btn-block" style="margin-top: 1rem;">Confirmer la demande de réservation</button>
                            </form>
                        </div>
                    </div>
                `;

                modal.classList.add('active');

                // Bind Tunnel Form
                const bookingForm = document.getElementById('bookingTunnelForm');
                bookingForm.addEventListener('submit', (e) => {
                    e.preventDefault();
                    modal.classList.remove('active');
                    showToast("Félicitations ! Votre demande de réservation a bien été enregistrée. Un conseiller personnel va prendre contact avec vous.");
                });
            }
        });
    });
}

// Toast notification helper
function showToast(message) {
    const toast = document.getElementById('toastNotification');
    if (!toast) return;

    toast.textContent = message;
    toast.classList.add('active');

    setTimeout(() => {
        toast.classList.remove('active');
    }, 4500);
}
