### 3. `js/script.js`
Logique complète : gestion des animations au scroll (`requestAnimationFrame`), pilotage du scroll-storytelling en 6 étapes, panier dynamique avec persistance (`localStorage`), validation du formulaire de contact et ergonomie mobile.

```javascript
/**
 * Developer Agent - JavaScript Engine
 * Architecture sans framework, haute performance, modulaire.
 */

document.addEventListener('DOMContentLoaded', () => {

    /* ==========================================================================
       1. INTERSECTION OBSERVER POUR LES ANIMATIONS D'APPARITION
       ========================================================================== */
    const observerOptions = {
        root: null,
        rootMargin: '0px',
        threshold: 0.15
    };

    const fadeInObserver = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('in-view');
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    document.querySelectorAll('.product-card, .manufacture .grid-2').forEach(el => {
        el.style.opacity = '0';
        el.style.transform = 'translateY(30px)';
        el.style.transition = 'opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1)';
        fadeInObserver.observe(el);
    });

    // Classe CSS injectée pour déclencher l'apparition fluide
    const styleSheet = document.styleSheets[0];
    try {
        styleSheet.insertRule('.in-view { opacity: 1 !important; transform: translateY(0) !important; }', styleSheet.cssRules.length);
    } catch (e) {
        console.warn('Style rule insertion error:', e);
    }


    /* ==========================================================================
       2. SCROLL-STORYTELLING EN 6 ÉTAPES (PILOTAGE DE LA MONTRE)
       ========================================================================== */
    const storySection = document.getElementById('story');
    const storyWatch = document.getElementById('storyWatch');
    const storySteps = document.querySelectorAll('.story-step');

    if (storySection && storyWatch && storySteps.length > 0) {
        // Activer la première étape par défaut
        storySteps[0].classList.add('active');

        window.addEventListener('scroll', () => {
            const rect = storySection.getBoundingClientRect();
            const sectionHeight = storySection.offsetHeight;
            const windowHeight = window.innerHeight;

            // Calcul de la progression du scroll dans la section (de 0 à 1)
            let scrollProgress = -rect.top / (sectionHeight - windowHeight);
            scrollProgress = Math.max(0, Math.min(1, scrollProgress));

            // Détermination de l'étape active (sur 6 étapes)
            const stepIndex = Math.min(
                Math.floor(scrollProgress * storySteps.length),
                storySteps.length - 1
            );

            storySteps.forEach((step, index) => {
                if (index === stepIndex) {
                    step.classList.add('active');
                } else {
                    step.classList.remove('active');
                }
            });

            // Pilotage dynamique de la transformation de la montre (zoom & rotation 3D)
            requestAnimationFrame(() => {
                const scale = 1 + (scrollProgress * 0.8); // Zoom progressif de 1 à 1.8
                const rotateDeg = scrollProgress * 360;  // Rotation complète de 0 à 360deg
                const translateY = scrollProgress * -50; // Légère translation verticale

                storyWatch.style.transform = `scale(${scale}) rotate(${rotateDeg}deg) translateY(${translateY}px)`;
            });
        });
    }


    /* ==========================================================================
       3. GESTION INTERACTIVE DU PANIER D'ACHAT & LOCALSTORAGE
       ========================================================================== */
    let cart = JSON.parse(localStorage.getItem('chronos_cart')) || [];

    const cartModal = document.getElementById('cartModal');
    const openCartBtn = document.getElementById('openCartBtn');
    const closeCartBtn = document.getElementById('closeCartBtn');
    const cartBackdrop = document.getElementById('cartBackdrop');
    const cartItemsContainer = document.getElementById('cartItemsContainer');
    const cartTotalPrice = document.getElementById('cartTotalPrice');
    const cartCountElement = document.querySelector('.cart-count');
    const checkoutBtn = document.getElementById('checkoutBtn');

    // Ouvrir / Fermer le panier modal
    const toggleCart = (isOpen) => {
        if (isOpen) {
            cartModal.classList.add('open');
            cartModal.setAttribute('aria-hidden', 'false');
        } else {
            cartModal.classList.remove('open');
            cartModal.setAttribute('aria-hidden', 'true');
        }
    };

    openCartBtn.addEventListener('click', () => toggleCart(true));
    closeCartBtn.addEventListener('click', () => toggleCart(false));
    cartBackdrop.addEventListener('click', () => toggleCart(false));

    // Ajouter un produit au panier
    document.querySelectorAll('.add-to-cart').forEach(button => {
        button.addEventListener('click', (e) => {
            const id = e.target.getAttribute('data-id');
            const name = e.target.getAttribute('data-name');
            const price = parseFloat(e.target.getAttribute('data-price'));

            const existingItem = cart.find(item => item.id === id);
            if (existingItem) {
                existingItem.quantity += 1;
            } else {
                cart.push({ id, name, price, quantity: 1 });
            }

            updateCart();
            toggleCart(true);
        });
    });

    // Mettre à jour l'affichage et le stockage du panier
    function updateCart() {
        localStorage.setItem('chronos_cart', JSON.stringify(cart));

        // Mettre à jour le compteur badge
        const totalCount = cart.reduce((sum, item) => sum + item.quantity, 0);
        cartCountElement.textContent = totalCount;

        // Rendu des articles dans le panneau
        if (cart.length === 0) {
            cartItemsContainer.innerHTML = '<p class="empty-cart-msg">Votre panier est actuellement vide.</p>';
            cartTotalPrice.textContent = '0 €';
            return;
        }

        cartItemsContainer.innerHTML = '';
        let totalPrice = 0;

        cart.forEach(item => {
            totalPrice += item.price * item.quantity;

            const itemEl = document.createElement('div');
            itemEl.className = 'cart-item';
            itemEl.innerHTML = `
                <div class="cart-item-info">
                    <h4>${item.name}</h4>
                    <span>${item.price.toLocaleString()} € x ${item.quantity}</span>
                </div>
                <button class="remove-item" data-id="${item.id}" aria-label="Supprimer l'article">&times;</button>
            `;
            cartItemsContainer.appendChild(itemEl);
        });

        cartTotalPrice.textContent = `${totalPrice.toLocaleString()} €`;

        // Activer les boutons de suppression d'article
        document.querySelectorAll('.remove-item').forEach(delBtn => {
            delBtn.addEventListener('click', (e) => {
                const id = e.target.getAttribute('data-id');
                cart = cart.filter(item => item.id !== id);
                updateCart();
            });
        });
    }

    // Initialiser le panier au chargement
    updateCart();

    // Simulation de validation de commande
    checkoutBtn.addEventListener('click', () => {
        if (cart.length === 0) return;
        alert('Merci pour votre confiance. Un conseiller privé CHRONOS & CO. va prendre contact avec vous pour finaliser la transaction sécurisée.');
        cart = [];
        updateCart();
        toggleCart(false);
    });


    /* ==========================================================================
       4. VALIDATION DU FORMULAIRE DE CONTACT
       ========================================================================== */
    const contactForm = document.getElementById('contactForm');
    const formFeedback = document.getElementById('formFeedback');

    if (contactForm) {
        contactForm.addEventListener('submit', (e) => {
            e.preventDefault();
            const emailInput = contactForm.querySelector('input[type="email"]');

            if (emailInput.value.trim() !== '') {
                formFeedback.classList.add('show');
                contactForm.reset();
                setTimeout(() => {
                    formFeedback.classList.remove('show');
                }, 4000);
            }
        });
    }

});
```

