### 2. Gestion du Stockage & Leaderboard (`js/storage.js`)

Gère la persistance des données (sauvegarde des configurations du garage et du classement des meilleurs temps).

```javascript
class GameStorage {
    static getLeaderboard() {
        const data = localStorage.getItem('apex_leaderboard');
        return data ? JSON.parse(data) : [
            { name: "Vortex", time: "01:12.45" },
            { name: "ApexKing", time: "01:15.10" },
            { name: "Roxie", time: "01:18.90" }
        ];
    }

    static saveScore(name, timeStr) {
        let lb = this.getLeaderboard();
        lb.push({ name, time: timeStr });
        lb.sort((a, b) => a.time.localeCompare(b.time));
        if (lb.length > 5) lb = lb.slice(0, 5);
        localStorage.setItem('apex_leaderboard', JSON.stringify(lb));
    }

    static getSettings() {
        const data = localStorage.getItem('apex_settings');
        return data ? JSON.parse(data) : { color: "#00f3ff", rims: "standard", engine: 1, grip: 1 };
    }

    static saveSettings(settings) {
        localStorage.setItem('apex_settings', JSON.stringify(settings));
    }
}
```

