### 4. Moteur Physique et Véhicule (`js/physics.js`)

Implémente le comportement dynamique du véhicule, la gestion de l'accélération, du freinage et un algorithme de dérapage (*drift*) basé sur la modification dynamique de l'adhérence latérale des roues.

```javascript
class CarPhysics {
    constructor(scene, world, isPlayer = true, color = "#00f3ff") {
        this.world = world;
        this.scene = scene;
        this.isPlayer = isPlayer;
        this.speed = 0;
        this.maxSpeed = 120;
        this.driftFactor = 1.0;

        // Configuration Mesh 3D de la voiture
        const geometry = new THREE.BoxGeometry(2, 0.8, 4);
        const material = new THREE.MeshStandardMaterial({ color: color, roughness: 0.3, metalness: 0.8 });
        this.mesh = new THREE.Mesh(geometry, material);
        this.mesh.castShadow = true;
        scene.add(this.mesh);

        // Configuration Physique Cannon.js
        const shape = new CANNON.Box(new CANNON.Vec3(1, 0.4, 2));
        this.body = new CANNON.Body({
            mass: 1500,
            position: new CANNON.Vec3(0, 2, 0),
            shape: shape
        });
        this.body.linearDamping = 0.5;
        this.body.angularDamping = 0.8;
        this.world.addBody(this.body);

        // Commandes
        this.controls = { forward: false, backward: false, left: false, right: false, drift: false };
        if (this.isPlayer) this.initInputListeners();
    }

    initInputListeners() {
        window.addEventListener('keydown', (e) => this.handleKey(e, true));
        window.addEventListener('keyup', (e) => this.handleKey(e, false));
    }

    handleKey(e, isDown) {
        switch(e.code) {
            case 'KeyW': case 'ArrowUp': this.controls.forward = isDown; break;
            case 'KeyS': case 'ArrowDown': this.controls.backward = isDown; break;
            case 'KeyA': case 'ArrowLeft': this.controls.left = isDown; break;
            case 'KeyD': case 'ArrowRight': this.controls.right = isDown; break;
            case 'Space': this.controls.drift = isDown; break;
        }
    }

    update(delta) {
        // Synchronisation Mesh 3D <-> Corps Physique
        this.mesh.position.copy(this.body.position);
        this.mesh.quaternion.copy(this.body.quaternion);

        // Gestion de la vitesse et de la force motrice
        let engineForce = 0;
        if (this.controls.forward) engineForce = 35000;
        if (this.controls.backward) engineForce = -15000;

        // Calcul dynamique du vecteur d'avancement
        const forwardVector = new CANNON.Vec3(0, 0, -1);
        this.body.quaternion.vmult(forwardVector, forwardVector);

        // Application de la force
        this.body.applyForce(forwardVector.scale(engineForce), this.body.position);

        // Gestion de la direction & Drift
        let turnSpeed = 2.5;
        if (this.controls.drift) {
            this.driftFactor = 2.5; // Réduit l'adhérence latérale pour glisser
            turnSpeed = 3.2;
        } else {
            this.driftFactor = 1.0;
        }

        if (this.controls.left) {
            this.body.angularVelocity.y = turnSpeed;
        } else if (this.controls.right) {
            this.body.angularVelocity.y = -turnSpeed;
        } else {
            this.body.angularVelocity.y *= 0.9; // Amortissement
        }

        // Calcul de la vitesse actuelle (Km/h)
        this.speed = this.body.velocity.length() * 3.6;
    }

    setColor(colorHex) {
        this.mesh.material.color.set(colorHex);
    }
}
