### 6. Intelligence Artificielle (IA) des Adversaires (`js/ai.js`)

Implémente un système de navigation basé sur des waypoints (points de passage) permettant aux adversaires de parcourir le circuit de manière compétitive.

```javascript
class RacingAI {
    static getWaypoints() {
        return [
            new CANNON.Vec3(0, 0, -100),
            new CANNON.Vec3(0, 0, 100)
        ];
    }

    constructor(car, waypoints) {
        this.car = car;
        this.waypoints = waypoints;
        this.currentWaypointIndex = 0;
    }

    update() {
        const target = this.waypoints[this.currentWaypointIndex];
        const carPos = this.car.body.position;

        // Calcul de la distance au waypoint actuel
        const distance = carPos.distanceTo(target);
        if (distance < 20) {
            this.currentWaypointIndex = (this.currentWaypointIndex + 1) % this.waypoints.length;
        }

        // Pilotage automatique simulé
        this.car.controls.forward = true;

        // Orientation vers le waypoint
        const direction = new CANNON.Vec3(target.x - carPos.x, 0, target.z - carPos.z);
        direction.normalize();

        const forward = new CANNON.Vec3(0, 0, -1);
        this.car.body.quaternion.vmult(forward, forward);

        const cross = forward.cross(direction);
        if (cross.y > 0.1) {
            this.car.body.angularVelocity.y = 2.0;
        } else if (cross.y < -0.1) {
            this.car.body.angularVelocity.y = -2.0;
        } else {
            this.car.body.angularVelocity.y = 0;
        }
    }
}
```

