### 3. `script.js`
Cœur logique du jeu : Moteur 3D Three.js, gestion physique des véhicules (accélération, dérapage, frottements), IA des adversaires, circuits, gestion des tours, LocalStorage et écouteurs clavier stricts (`Z`, `Q`, `S`, `D`).

```javascript
// --- CONFIGURATION & CLASSE PRINCIPALE ---
class ApexRacerGame {
    constructor() {
        this.currentScreen = 'main-menu';
        this.scene = null;
        this.camera = null;
        this.renderer = null;

        // Paramètres Voiture Joueur
        this.carConfig = {
            color: 0xff0055,
            speedMultiplier: 1.0
        };

        // État du Jeu
        this.gameState = 'MENU'; // MENU, RACING, GAMEOVER
        this.currentTrack = 'circuit1';
        this.lapsTotal = 3;
        this.currentLap = 1;
        this.startTime = 0;
        this.finishTime = 0;

        // Contrôles (Z, Q, S, D)
        this.keys = { z: false, q: false, s: false, d: false };

        // Physique Joueur
        this.playerCar = null;
        this.playerPhysics = {
            speed: 0,
            maxSpeed: 1.2,
            acceleration: 0.015,
            brake: 0.03,
            friction: 0.008,
            turnSpeed: 0.035,
            driftFactor: 0.92
        };

        // Adversaires IA
        this.aiCars = [];

        // Système de checkpoints / circuits
        this.checkpoints = [];
        this.playerCheckpointIndex = 0;

        this.initEngine();
        this.initListeners();
        this.loadLeaderboard();
    }

    // --- INITIALISATION MOTEUR 3D ---
    initEngine() {
        const container = document.getElementById('canvas-container');

        this.scene = new THREE.Scene();
        this.scene.background = new THREE.Color(0x0b0b10);
        this.scene.fog = new THREE.FogExp2(0x0b0b10, 0.015);

        this.camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 1000);

        this.renderer = new THREE.WebGLRenderer({ antialias: true });
        this.renderer.setSize(window.innerWidth, window.innerHeight);
        this.renderer.shadowMap.enabled = true;
        container.appendChild(this.renderer.domElement);

        // Éclairage
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        this.scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0x00f3ff, 0.8);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        this.scene.add(dirLight);

        // Génération de la voiture du garage (aperçu)
        this.buildGaragePreviewCar();

        // Boucle de rendu
        window.addEventListener('resize', () => this.onWindowResize());
        this.animate();
    }

    // --- GESTION DES INTERFACES (UI) ---
    showScreen(screenId) {
        document.querySelectorAll('.ui-screen').forEach(s => s.classList.add('hidden'));
        document.getElementById('hud').classList.add('hidden');

        if (screenId === 'hud-active') {
            document.getElementById('hud').classList.remove('hidden');
            this.gameState = 'RACING';
        } else {
            document.getElementById(screenId).classList.remove('hidden');
            this.gameState = 'MENU';
            if (screenId === 'garage-screen') {
                this.setupGarageScene();
            }
        }
        this.currentScreen = screenId;
    }

    // --- CONTRÔLES CLAVIER STRICTS (Z, Q, S, D) ---
    initListeners() {
        window.addEventListener('keydown', (e) => this.handleKey(e, true));
        window.addEventListener('keyup', (e) => this.handleKey(e, false));
    }

    handleKey(e, isDown) {
        const k = e.key.toLowerCase();
        if (k === 'z') this.keys.z = isDown;
        if (k === 'q') this.keys.q = isDown;
        if (k === 's') this.keys.s = isDown;
        if (k === 'd') this.keys.d = isDown;
    }

    // --- CRÉATION DE VÉHICULE 3D ---
    createCarMesh(colorHex) {
        const carGroup = new THREE.Group();

        // Châssis principal
        const bodyGeo = new THREE.BoxGeometry(1.8, 0.6, 4);
        const bodyMat = new THREE.MeshStandardMaterial({ color: colorHex, roughness: 0.3, metalness: 0.8 });
        const body = new THREE.Mesh(bodyGeo, bodyMat);
        body.position.y = 0.5;
        body.castShadow = true;
        carGroup.add(body);

        // Habitacle
        const cabinGeo = new THREE.BoxGeometry(1.4, 0.5, 2);
        const cabinMat = new THREE.MeshStandardMaterial({ color: 0x111111, roughness: 0.1, metalness: 0.9 });
        const cabin = new THREE.Mesh(cabinGeo, cabinMat);
        cabin.position.set(0, 0.9, -0.2);
        carGroup.add(cabin);

        // Roues
        const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.3, 16);
        wheelGeo.rotateX(Math.PI / 2);
        const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222 });

        const positions = [
            [-1, 0.4, 1.3], [1, 0.4, 1.3],
            [-1, 0.4, -1.3], [1, 0.4, -1.3]
        ];

        carGroup.wheels = [];
        positions.forEach(pos => {
            const wheel = new THREE.Mesh(wheelGeo, wheelMat);
            wheel.position.set(...pos);
            carGroup.add(wheel);
            carGroup.wheels.push(wheel);
        });

        return carGroup;
    }

    // --- GARAGE & PERSONNALISATION ---
    setupGarageScene() {
        this.clearSceneObjects();
        this.playerCar = this.createCarMesh(this.carConfig.color);
        this.scene.add(this.playerCar);
        this.camera.position.set(0, 3, 7);
        this.camera.lookAt(0, 0.5, 0);
    }

    buildGaragePreviewCar() {
        // Initialisation silencieuse
    }

    updateCarColor(hexColor) {
        this.carConfig.color = parseInt(hexColor.replace('#', '0x'));
        if (this.playerCar) {
            this.scene.remove(this.playerCar);
            this.playerCar = this.createCarMesh(this.carConfig.color);
            this.scene.add(this.playerCar);
        }
    }

    upgradeCar(type) {
        if (type === 'speed') {
            this.carConfig.speedMultiplier += 0.15;
            alert("Moteur amélioré ! Vitesse max augmentée.");
        }
    }

    // --- CONSTRUCTION DES CIRCUITS ---
    startRace(trackName) {
        this.currentTrack = trackName;
        this.clearSceneObjects();
        this.currentLap = 1;
        this.playerCheckpointIndex = 0;
        document.getElementById('current-lap').innerText = this.currentLap;

        // Génération de l'environnement de course
        this.buildTrack(trackName);

        // Création du joueur sur la grille de départ
        this.playerCar = this.createCarMesh(this.carConfig.color);
        this.playerCar.position.set(0, 0, 0);
        this.scene.add(this.playerCar);
        this.playerPhysics.speed = 0;

        // Création des IA
        this.initAIAdversaries();

        this.startTime = performance.now();
        this.showScreen('hud-active');
    }

    buildTrack(trackName) {
        // Sol général
        const groundGeo = new THREE.PlaneGeometry(1000, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x151520 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.receiveShadow = true;
        this.scene.add(ground);

        this.checkpoints = [];

        if (trackName === 'circuit1') {
            // Circuit Ovale simple
            const trackGeo = new THREE.RingGeometry(35, 65, 32);
            const trackMat = new THREE.MeshStandardMaterial({ color: 0x2b2b3d, side: THREE.DoubleSide });
            const track = new THREE.Mesh(trackGeo, trackMat);
            track.rotation.x = -Math.PI / 2;
            track.position.y = 0.05;
            this.scene.add(track);

            // Checkpoints fictifs sur l'ovale
            for (let i = 0; i < 4; i++) {
                const angle = (i / 4) * Math.PI * 2;
                this.checkpoints.push(new THREE.Vector3(Math.cos(angle) * 50, 0, Math.sin(angle) * 50));
            }
        } else {
            // Circuit Technique (Tracé sinueux composé de segments)
            const trackMat = new THREE.MeshStandardMaterial({ color: 0x2b2b3d });

            // Ligne droite principale
            const s1 = new THREE.Mesh(new THREE.PlaneGeometry(20, 150), trackMat);
            s1.rotation.x = -Math.PI / 2;
            s1.position.set(0, 0.05, 0);
            this.scene.add(s1);

            this.checkpoints.push(new THREE.Vector3(0, 0, -60));
            this.checkpoints.push(new THREE.Vector3(0, 0, 60));
            this.checkpoints.push(new THREE.Vector3(40, 0, 0));
            this.checkpoints.push(new THREE.Vector3(-40, 0, 0));
        }
    }

    initAIAdversaries() {
        this.aiCars = [];
        const aiColors = [0x00ff55, 0xffaa00, 0xaa00ff];

        for (let i = 0; i < 3; i++) {
            const ai = this.createCarMesh(aiColors[i]);
            ai.position.set((i + 1) * 3, 0, 5 + i * 2);
            ai.aiData = {
                targetCheckpoint: 0,
                speed: 0.6 + Math.random() * 0.2
            };
            this.scene.add(ai);
            this.aiCars.push(ai);
        }
    }

    clearSceneObjects() {
        while(this.scene.children.length > 0){ 
            this.scene.remove(this.scene.children[0]); 
        }
        // Remettre les lumières de base
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        this.scene.add(ambientLight);
        const dirLight = new THREE.DirectionalLight(0x00f3ff, 0.8);
        dirLight.position.set(50, 100, 50);
        this.scene.add(dirLight);
    }

    // --- BOUCLE DE JEU & PHYSIQUE ---
    animate() {
        requestAnimationFrame(() => this.animate());

        if (this.gameState === 'RACING') {
            this.updatePlayerPhysics();
            this.updateAI();
            this.updateCamera();
            this.checkLapProgression();
        }

        this.renderer.render(this.scene, this.camera);
    }

    updatePlayerPhysics() {
        if (!this.playerCar) return;

        const p = this.playerPhysics;

        // Gestion Accélération / Recul (Z / S)
        if (this.keys.z) {
            p.speed += p.acceleration * p.speedMultiplier;
        } else if (this.keys.s) {
            p.speed -= p.brake;
        } else {
            // Frottements naturels
            if (p.speed > 0) p.speed -= p.friction;
            if (p.speed < 0) p.speed += p.friction;
        }

        // Limitation vitesses
        p.speed = Math.max(-p.maxSpeed * 0.4, Math.min(p.speed, p.maxSpeed * p.speedMultiplier));

        // Direction / Dérapage (Q / D)
        if (Math.abs(p.speed) > 0.05) {
            let steering = p.turnSpeed * (p.speed / p.maxSpeed);
            if (this.keys.q) this.playerCar.rotation.y += steering;
            if (this.keys.d) this.playerCar.rotation.y -= steering;
        }

        // Mouvement de la voiture selon son orientation
        this.playerCar.translateZ(p.speed);

        // Mise à jour affichage vitesse HUD
        document.getElementById('speedometer').innerHTML = Math.round(Math.abs(p.speed) * 160) + ' <span class="unit">KM/H</span>';
    }

    updateAI() {
        this.aiCars.forEach(ai => {
            // IA simple suivant les checkpoints
            if (this.checkpoints.length > 0) {
                const target = this.checkpoints[ai.aiData.targetCheckpoint];
                ai.lookAt(target.x, ai.position.y, target.z);
                ai.translateZ(ai.aiData.speed);

                if (ai.position.distanceTo(target) < 15) {
                    ai.aiData.targetCheckpoint = (ai.aiData.targetCheckpoint + 1) % this.checkpoints.length;
                }
            }
        });
    }

    updateCamera() {
        // Caméra poursuite fluide derrière le joueur
        const idealOffset = new THREE.Vector3(0, 3.5, -7);
        idealOffset.applyQuaternion(this.playerCar.quaternion);
        idealOffset.add(this.playerCar.position);

        this.camera.position.lerp(idealOffset, 0.1);

        const lookAtTarget = this.playerCar.position.clone();
        lookAtTarget.y += 1;
        this.camera.lookAt(lookAtTarget);
    }

    checkLapProgression() {
        // Gestion simplifiée du passage de ligne d'arrivée (Z proche de 0)
        if (this.playerCar.position.z > 45 && this.playerCar.position.z < 50 && Math.abs(this.playerCar.position.x) < 10) {
            // Anti-spam de validation de tour immédiat via délai
            if (!this.cooldownLap) {
                this.currentLap++;
                this.cooldownLap = true;
                setTimeout(() => this.cooldownLap = false, 3000);

                if (this.currentLap > this.lapsTotal) {
                    this.endRace();
                } else {
                    document.getElementById('current-lap').innerText = this.currentLap;
                }
            }
        }
    }

    endRace() {
        this.gameState = 'GAMEOVER';
        const finishTimeMs = performance.now() - this.startTime;
        const seconds = (finishTimeMs / 1000).toFixed(3);

        document.getElementById('game-over-title').innerText = "Victoire ! Course Bouclée";
        document.getElementById('game-over-time').innerText = `Temps total : ${seconds} secondes`;

        this.saveScore(seconds);
        this.showScreen('game-over-screen');
    }

    onWindowResize() {
        this.camera.aspect = window.innerWidth / window.innerHeight;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(window.innerWidth, window.innerHeight);
    }

    // --- GESTION DES SCORES (LOCALSTORAGE) ---
    saveScore(time) {
        let scores = JSON.parse(localStorage.getItem('apex_racer_scores') || '[]');
        scores.push(parseFloat(time));
        scores.sort((a, b) => a - b);
        scores = scores.slice(0, 5); // Garder le top 5
        localStorage.setItem('apex_racer_scores', JSON.stringify(scores));
        this.loadLeaderboard();
    }

    loadLeaderboard() {
        const listEl = document.getElementById('leaderboard-list');
        if (!listEl) return;

        listEl.innerHTML = '';
        let scores = JSON.parse(localStorage.getItem('apex_racer_scores') || '[]');

        if (scores.length === 0) {
            listEl.innerHTML = '<li>Aucun temps enregistré</li>';
            return;
        }

        scores.forEach((score, index) => {
            const li = document.createElement('li');
            li.innerText = `#${index + 1} - ${score} secondes`;
            listEl.appendChild(li);
        });
    }
}

// Lancement global de l'application au chargement
window.addEventListener('DOMContentLoaded', () => {
    window.game = new ApexRacerGame();
});
