```javascript
// ==========================================
// GESTIONNAIRE GLOBAL DU JEU & UI
// ==========================================
const Game = {
    currentScreen: 'main-menu',
    selectedCarIndex: 0,
    selectedTrackIndex: 0,
    aiDifficulty: 'normal',
    totalLaps: 3,

    showScreen(screenId) {
        document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
        document.getElementById(screenId).classList.add('active');
        this.currentScreen = screenId;
        if (screenId === 'game-screen') {
            Engine.init();
        } else {
            Engine.stop();
        }
    },

    selectCar(index, element) {
        this.selectedCarIndex = index;
        document.querySelectorAll('.car-card').forEach(c => c.classList.remove('selected'));
        element.classList.add('selected');
    },

    selectTrack(index, element) {
        this.selectedTrackIndex = index;
        document.querySelectorAll('.track-card').forEach(c => c.classList.remove('selected'));
        element.classList.add('selected');
    },

    setDifficulty(val) { this.aiDifficulty = val; },
    setLaps(val) { this.totalLaps = parseInt(val) || 3; document.getElementById('max-laps-display').innerText = this.totalLaps; },

    startRace() {
        this.showScreen('game-screen');
    },

    restartRace() {
        this.showScreen('game-screen');
    },

    endGame(rankings) {
        Engine.stop();
        this.showScreen('gameover-screen');
        const container = document.getElementById('results-container');
        container.innerHTML = '<h3>Classement Final</h3>';
        rankings.forEach((r, idx) => {
            container.innerHTML += `<div class="result-row"><span>#${idx + 1} ${r.name}</span><span>${r.time}</span></div>`;
        });
    }
};

// ==========================================
// CONFIGURATION DES CIRCUITS (WAYPOINTS)
// ==========================================
const Tracks = [
    // Circuit 1: Oval Classique
    {
        width: 3000,
        height: 3000,
        startLine: { x: 1500, y: 2500, angle: -Math.PI / 2 },
        waypoints: [
            { x: 1500, y: 2500 },
            { x: 2400, y: 2200 },
            { x: 2700, y: 1500 },
            { x: 2400, y: 800 },
            { x: 1500, y: 500 },
            { x: 600, y: 800 },
            { x: 300, y: 1500 },
            { x: 600, y: 2200 }
        ]
    },
    // Circuit 2: Technique
    {
        width: 3000,
        height: 3000,
        startLine: { x: 1500, y: 2500, angle: -Math.PI / 2 },
        waypoints: [
            { x: 1500, y: 2500 },
            { x: 2200, y: 2500 },
            { x: 2600, y: 2000 },
            { x: 2100, y: 1500 },
            { x: 2500, y: 1000 },
            { x: 1800, y: 600 },
            { x: 1200, y: 800 },
            { x: 800, y: 1200 },
            { x: 1400, y: 1700 },
            { x: 600, y: 2000 }
        ]
    }
];

// ==========================================
// CLASSE VEHICULE (PHYSIQUE & RENDU)
// ==========================================
class Vehicle {
    constructor(x, y, angle, color, isAI = false, stats = {}) {
        this.x = x;
        this.y = y;
        this.angle = angle;
        this.color = color;
        this.isAI = isAI;

        // Physique
        this.speed = 0;
        this.maxSpeed = stats.maxSpeed || 12;
        this.acceleration = stats.acceleration || 0.2;
        this.braking = stats.braking || 0.4;
        this.friction = stats.friction || 0.05;
        this.turnSpeed = stats.turnSpeed || 0.04;
        this.driftFactor = stats.driftFactor || 0.92;

        this.width = 30;
        this.height = 60;
        this.steerAngle = 0;
        this.velocity = { x: 0, y: 0 };

        // Course
        this.currentLap = 1;
        this.nextWaypointIndex = 0;
        this.finishTime = null;
        this.isFinished = false;
        this.smokeParticles = [];
    }

    update(input, track) {
        if (this.isFinished) return;

        if (!this.isAI) {
            // Contrôles Joueur
            if (input.up) {
                this.speed = Math.min(this.speed + this.acceleration, this.maxSpeed);
            } else if (input.down) {
                this.speed = Math.max(this.speed - this.acceleration, -this.maxSpeed / 2);
            } else {
                if (this.speed > 0) this.speed = Math.max(0, this.speed - this.friction);
                if (this.speed < 0) this.speed = Math.min(0, this.speed + this.friction);
            }

            if (input.brake) {
                this.speed *= 0.85; // Frein à main / Drift fort
                this.createSmoke();
            }

            if (Math.abs(this.speed) > 0.5) {
                let direction = this.speed >= 0 ? 1 : -1;
                if (input.left) this.angle -= this.turnSpeed * direction;
                if (input.right) this.angle += this.turnSpeed * direction;
            }
        } else {
            // IA basique de suivi de waypoints
            this.updateAI(track);
        }

        // Physique d'inertie & Drift
        let targetVelX = Math.cos(this.angle) * this.speed;
        let targetVelY = Math.sin(this.angle) * this.speed;

        this.velocity.x = this.velocity.x * this.driftFactor + targetVelX * (1 - this.driftFactor);
        this.velocity.y = this.velocity.y * this.driftFactor + targetVelY * (1 - this.driftFactor);

        this.x += this.velocity.x;
        this.y += this.velocity.y;

        // Gestion de la fumée de dérapage
        if (Math.abs(this.speed) > 6 && !this.isAI && Math.random() < 0.3) {
            this.createSmoke();
        }
        this.updateSmoke();

        // Détection passage de ligne & waypoints
        this.checkCheckpoints(track);
    }

    updateAI(track) {
        const wp = track.waypoints[this.nextWaypointIndex];
        const dx = wp.x - this.x;
        const dy = wp.y - this.y;
        const targetAngle = Math.atan2(dy, dx);

        // Ajustement progressif de l'angle
        let angleDiff = targetAngle - this.angle;
        while (angleDiff < -Math.PI) angleDiff += Math.PI * 2;
        while (angleDiff > Math.PI) angleDiff -= Math.PI * 2;

        if (angleDiff > 0.1) this.angle += this.turnSpeed;
        else if (angleDiff < -0.1) this.angle -= this.turnSpeed;

        // Vitesse IA selon difficulté
        let targetSpeed = 8;
        if (Game.aiDifficulty === 'easy') targetSpeed = 7;
        if (Game.aiDifficulty === 'hard') targetSpeed = 10.5;

        if (this.speed < targetSpeed) this.speed += this.acceleration;
        else this.speed -= this.friction;

        // Distance waypoint
        if (Math.hypot(dx, dy) < 200) {
            this.nextWaypointIndex = (this.nextWaypointIndex + 1) % track.waypoints.length;
        }
    }

    checkCheckpoints(track) {
        const wp = track.waypoints[this.nextWaypointIndex];
        const dist = Math.hypot(wp.x - this.x, wp.y - this.y);
        if (dist < 250 && this.isAI) {
            this.nextWaypointIndex = (this.nextWaypointIndex + 1) % track.waypoints.length;
        }

        // Ligne d'arrivée
        const sf = track.startLine;
        const dFinish = Math.hypot(sf.x - this.x, sf.y - this.y);
        if (dFinish < 80 && !this.cooldownFinish) {
            if (this.nextWaypointIndex === 1 || this.nextWaypointIndex === 0) {
                this.currentLap++;
                this.cooldownFinish = true;
                setTimeout(() => this.cooldownFinish = false, 3000);

                if (this.currentLap > Game.totalLaps && !this.isFinished) {
                    this.isFinished = true;
                    this.finishTime = Engine.raceTime;
                    Engine.checkRaceOver();
                }
            }
        }
    }

    createSmoke() {
        this.smokeParticles.push({
            x: this.x - Math.cos(this.angle) * 20,
            y: this.y - Math.sin(this.angle) * 20,
            alpha: 1,
            size: Math.random() * 8 + 4
        });
    }

    updateSmoke() {
        for (let i = this.smokeParticles.length - 1; i >= 0; i--) {
            let p = this.smokeParticles[i];
            p.alpha -= 0.03;
            p.size += 0.2;
            if (p.alpha <= 0) this.smokeParticles.splice(i, 1);
        }
    }

    draw(ctx) {
        // Dessin Fumée
        ctx.save();
        this.smokeParticles.forEach(p => {
            ctx.fillStyle = `rgba(200, 200, 200, ${p.alpha})`;
            ctx.beginPath();
            ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
            ctx.fill();
        });
        ctx.restore();

        // Dessin Véhicule
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);

        // Carrosserie
        ctx.fillStyle = this.color;
        ctx.fillRect(-this.height / 2, -this.width / 2, this.height, this.width);

        // Pare-brise
        ctx.fillStyle = '#111';
        ctx.fillRect(-5, -this.width / 2 + 4, 15, this.width - 8);

        // Roues
        ctx.fillStyle = '#000';
        ctx.fillRect(-this.height / 3, -this.width / 2 - 4, 12, 6);
        ctx.fillRect(this.height / 4, -this.width / 2 - 4, 12, 6);
        ctx.fillRect(-this.height / 3, this.width / 2 - 2, 12, 6);
        ctx.fillRect(this.height / 4, this.width / 2 - 2, 12, 6);

        ctx.restore();
    }
}

// ==========================================
// MOTEUR PRINCIPAL DU JEU (CANVAS & BOUCLE)
// ==========================================
const Engine = {
    canvas: null,
    ctx: null,
    minimapCanvas: null,
    miniCtx: null,
    width: 0,
    height: 0,
    animId: null,
    raceTime: 0,
    startTime: 0,
    isRun: false,

    keys: { up: false, down: false, left: false, right: false, brake: false },
    player: null,
    cars: [],
    track: null,

    init() {
        this.canvas = document.getElementById('gameCanvas');
        this.ctx = this.canvas.getContext('2d');
        this.minimapCanvas = document.getElementById('minimapCanvas');
        this.miniCtx = this.minimapCanvas.getContext('2d');

        this.resize();
        window.addEventListener('resize', () => this.resize());

        // Chargement du circuit
        this.track = Tracks[Game.selectedTrackIndex];

        // Création Véhicules
        const carConfigs = [
            { maxSpeed: 13, acceleration: 0.25, turnSpeed: 0.045 }, // Rouge
            { maxSpeed: 14.5, acceleration: 0.18, turnSpeed: 0.038, driftFactor: 0.94 }, // Bleue
            { maxSpeed: 11.5, acceleration: 0.3, turnSpeed: 0.05, driftFactor: 0.88 }  // Jaune
        ];
        let pConfig = carConfigs[Game.selectedCarIndex];
        let pColors = ['#e94560', '#3498db', '#f1c40f'];

        this.player = new Vehicle(this.track.startLine.x, this.track.startLine.y, this.track.startLine.angle, pColors[Game.selectedCarIndex], false, pConfig);

        this.cars = [this.player];
        // 4 Voitures IA
        const aiColors = ['#e74c3c', '#2ecc71', '#9b59b6', '#e67e22'];
        for (let i = 0; i < 4; i++) {
            let aiCar = new Vehicle(
                this.track.startLine.x + (i + 1) * 40, 
                this.track.startLine.y + (i % 2 === 0 ? 40 : -40), 
                this.track.startLine.angle, 
                aiColors[i], 
                true, 
                { maxSpeed: 10 + Math.random() * 2, turnSpeed: 0.04 }
            );
            aiCar.nextWaypointIndex = 1;
            this.cars.push(aiCar);
        }

        // Écouteurs Clavier
        window.addEventListener('keydown', e => this.handleKey(e, true));
        window.addEventListener('keyup', e => this.handleKey(e, false));

        this.startTime = Date.now();
        this.isRun = true;
        this.loop();
    },

    resize() {
        this.canvas.width = window.innerWidth;
        this.canvas.height = window.innerHeight;
    },

    stop() {
        this.isRun = false;
        cancelAnimationFrame(this.animId);
        window.removeEventListener('keydown', e => this.handleKey(e, true));
        window.removeEventListener('keyup', e => this.handleKey(e, false));
    },

    handleKey(e, isDown) {
        switch (e.key.toLowerCase()) {
            case 'z': case 'arrowup': this.keys.up = isDown; break;
            case 's': case 'arrowdown': this.keys.down = isDown; break;
            case 'q': case 'arrowleft': this.keys.left = isDown; break;
            case 'd': case 'arrowright': this.keys.right = isDown; break;
            case ' ': this.keys.brake = isDown; break;
        }
    },

    loop() {
        if (!this.isRun) return;

        this.update();
        this.draw();

        this.animId = requestAnimationFrame(() => this.loop());
    },

    update() {
        this.raceTime = (Date.now() - this.startTime) / 1000;

        // Mise à jour voitures
        this.cars.forEach(car => car.update(this.keys, this.track));

        // Mise à jour HUD Texte
        document.getElementById('speed-display').innerText = Math.round(Math.abs(this.player.speed) * 15);
        document.getElementById('lap-display').innerText = Math.min(this.player.currentLap, Game.totalLaps);

        let mins = Math.floor(this.raceTime / 60).toString().padStart(2, '0');
        let secs = (this.raceTime % 60).toFixed(2).padStart(5, '0');
        document.getElementById('time-display').innerText = `${mins}:${secs}`;

        // Calcul position joueur
        let sorted = [...this.cars].sort((a, b) => {
            if (b.currentLap !== a.currentLap) return b.currentLap - a.currentLap;
            return b.nextWaypointIndex - a.nextWaypointIndex;
        });
        let playerRank = sorted.indexOf(this.player) + 1;
        document.getElementById('position-display').innerText = playerRank;
    },

    draw() {
        const ctx = this.ctx;
        ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

        // Caméra centrée sur le joueur
        ctx.save();
        ctx.translate(this.canvas.width / 2 - this.player.x, this.canvas.height / 2 - this.player.y);

        // 1. Rendu Circuit
        this.drawTrack(ctx);

        // 2. Rendu Véhicules
        this.cars.forEach(car => car.draw(ctx));

        ctx.restore();

        // 3. Rendu Mini-carte
        this.drawMinimap();
    },

    drawTrack(ctx) {
        const t = this.track;
        // Herbe de fond
        ctx.fillStyle = '#27ae60';
        ctx.fillRect(0, 0, t.width, t.height);

        // Piste Asphalte (Gros circuit ovale/technique)
        ctx.strokeStyle = '#34495e';
        ctx.lineWidth = 260;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';
        ctx.beginPath();
        ctx.moveTo(t.waypoints[0].x, t.waypoints[0].y);
        t.waypoints.forEach(wp => ctx.lineTo(wp.x, wp.y));
        ctx.closePath();
        ctx.stroke();

        // Bordures Rouges et Blanches (Vérins/Cordons de piste)
        ctx.strokeStyle = '#c0392b';
        ctx.lineWidth = 272;
        ctx.setDash=[20, 20];
        ctx.stroke();

        // Intérieur de piste (Repeindre l'herbe au centre pour garder l'effet anneau)
        ctx.fillStyle = '#27ae60';
        ctx.beginPath();
        // Dessin simplifié de la zone intérieure
        ctx.arc(t.width / 2, t.height / 2, 700, 0, Math.PI * 2);
        ctx.fill();

        // Ligne de départ / arrivée
        ctx.save();
        ctx.translate(t.startLine.x, t.startLine.y);
        ctx.rotate(t.startLine.angle);
        ctx.fillStyle = '#fff';
        for (let i = -60; i < 60; i += 15) {
            ctx.fillRect(i, -130, 15, 260);
        }
        ctx.restore();
    },

    drawMinimap() {
        const mCtx = this.miniCtx;
        const mW = this.minimapCanvas.width;
        const mH = this.minimapCanvas.height;
        const t = this.track;

        mCtx.clearRect(0, 0, mW, mH);

        let scaleX = mW / t.width;
        let scaleY = mH / t.height;

        // Tracé piste miniature
        mCtx.strokeStyle = '#7f8c8d';
        mCtx.lineWidth = 8;
        mCtx.beginPath();
        mCtx.moveTo(t.waypoints[0].x * scaleX, t.waypoints[0].y * scaleY);
        t.waypoints.forEach(wp => mCtx.lineTo(wp.x * scaleX, wp.y * scaleY));
        mCtx.closePath();
        mCtx.stroke();

        // Positions voitures sur minimap
        this.cars.forEach(car => {
            mCtx.fillStyle = car === this.player ? '#e94560' : '#f1c40f';
            mCtx.beginPath();
            mCtx.arc(car.x * scaleX, car.y * scaleY, car === this.player ? 4 : 2, 0, Math.PI * 2);
            mCtx.fill();
        });
    },

    checkRaceOver() {
        let allFinished = this.cars.every(c => c.isFinished);
        if (allFinished || this.player.isFinished) {
            setTimeout(() => {
                let rankings = [...this.cars].sort((a, b) => {
                    if (a.finishTime !== b.finishTime) return (a.finishTime || 9999) - (b.finishTime || 9999);
                    return 0;
                }).map((c, idx) => ({
                    name: c === this.player ? 'Joueur (Vous)' : `IA Adversaire ${idx}`,
                    time: c.finishTime ? `${Math.floor(c.finishTime/60).toString().padStart(2, '0')}:${(c.finishTime%60).toFixed(2).padStart(5, '0')}` : 'DNF'
                }));
                Game.endGame(rankings);
            }, 1500);
        }
    }
};
```

