  provider = "prisma-client-js"
}

model User {
  id            String       @id @default(uuid())
  name          String
  email         String       @unique
  password      String
  city          String
  neighborhood  String
  credits       Int          @default(10) // Crédit initial offert
  createdAt     DateTime     @default(now())

  skillsOffered Skill[]      @relation("OfferedSkills")
  skillsWanted  Skill[]      @relation("WantedSkills")

  sentExchanges     Exchange[] @relation("ExchangeRequester")
  receivedExchanges Exchange[] @relation("ExchangeProvider")

  sentMessages      Message[]  @relation("SentMessages")
  receivedMessages  Message[]  @relation("ReceivedMessages")
}

model Skill {
  id          String   @id @default(uuid())
  title       String
  category    String
  description String
  type        String   @default("OFFER") // OFFER ou WANT
  userId      String
  user        User     @relation("OfferedSkills", fields: [userId], references: [id], onDelete: Cascade)
  wantedUserId String?
  wantedUser  User?    @relation("WantedSkills", fields: [wantedUserId], references: [id], onDelete: Cascade)
}

model Exchange {
  id          String   @id @default(uuid())
  requesterId String
  requester   User     @relation("ExchangeRequester", fields: [requesterId], references: [id])
