### 2. Backend - Serveur & Logique Métier (`backend/src/server.js`)

```javascript
require('dotenv').config();
const express = require('express');
const cors = require('cors');
const { PrismaClient } = require('@prisma/client');
const bcrypt = require('bcryptjs');
const jwt = require('jsonwebtoken');

const prisma = new PrismaClient();
const app = express();

app.use(express.json());
app.use(cors());

const JWT_SECRET = process.env.JWT_SECRET || 'super_secret_sel_key';

// Middleware d'authentification JWT
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401);

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
};

// --- AUTHENTIFICATION ---
app.post('/api/auth/register', async (req, res) => {
  try {
    const { name, email, password, city, neighborhood } = req.body;
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await prisma.user.create({
      data: { name, email, password: hashedPassword, city, neighborhood, credits: 10 }
    });
    res.status(201).json({ message: "Utilisateur créé avec succès" });
  } catch (error) {
    res.status(400).json({ error: "Erreur lors de l'inscription (Email potentiellement déjà utilisé)" });
  }
});

app.post('/api/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    const user = await prisma.user.findUnique({ where: { email } });
    if (!user || !(await bcrypt.compare(password, user.password))) {
      return res.status(400).json({ error: "Identifiants invalides" });
    }
    const token = jwt.sign({ userId: user.id }, JWT_SECRET, { expiresIn: '24h' });
    res.json({ token, user: { id: user.id, name: user.name, email: user.email, credits: user.credits, city: user.city, neighborhood: user.neighborhood } });
  } catch (error) {
    res.status(500).json({ error: "Erreur serveur" });
  }
});

// --- UTILISATEURS & PROFIL ---
app.get('/api/users/me', authenticateToken, async (req, res) => {
  const user = await prisma.user.findUnique({
    where: { id: req.user.userId },
    include: { skillsOffered: true, skillsWanted: true }
  });
  res.json(user);
});

// --- COMPÉTENCES & RECHERCHE GÉOGRAPHIQUE ---
app.get('/api/skills', async (req, res) => {
  const { search, city, neighborhood } = req.query;
  try {
    const skills = await prisma.skill.findMany({
      where: {
        type: 'OFFER',
        AND: [
          search ? { OR: [{ title: { contains: search, mode: 'insensitive' } }, { description: { contains: search, mode: 'insensitive' } }] } : {},
          city ? { user: { city: { contains: city, mode: 'insensitive' } } } : {},
          neighborhood ? { user: { neighborhood: { contains: neighborhood, mode: 'insensitive' } } } : {}
        ]
      },
      include: { user: { select: { id: true, name: true, city: true, neighborhood: true, credits: true } } }
    });
    res.json(skills);
  } catch (e) {
    res.status(500).json({ error: "Erreur lors de la récupération des savoirs" });
  }
});

app.post('/api/skills', authenticateToken, async (req, res) => {
  const { title, category, description } = req.body;
  const skill = await prisma.skill.create({
    data: { title, category, description, type: 'OFFER', userId: req.user.userId }
  });
  res.status(201).json(skill);
});

// --- ÉCHANGES & SYSTÈME DE CRÉDITS TEMPS (1h = 1 crédit) ---
app.post('/api/exchanges', authenticateToken, async (req, res) => {
  const { providerId, skillId, hours } = req.body;
  if (providerId === req.user.userId) return res.status(400).json({ error: "Auto-échange impossible" });

  const exchange = await prisma.exchange.create({
    data: { requesterId: req.user.userId, providerId, skillId, hours, status: 'PENDING' }
  });
  res.status(201).json(exchange);
});

app.get('/api/exchanges', authenticateToken, async (req, res) => {
  const exchanges = await prisma.exchange.findMany({
    where: { OR: [{ requesterId: req.user.userId }, { providerId: req.user.userId }] },
    include: { requester: true, provider: true, skill: true }
  });
  res.json(exchanges);
});

// Validation croisée et transfert de crédits sécurisé en Transaction ACID
app.put('/api/exchanges/:id/complete', authenticateToken, async (req, res) => {
  const { id } = req.params;
  try {
    const exchange = await prisma.exchange.findUnique({ where: { id } });
    if (!exchange) return res.status(404).json({ error: "Échange introuvable" });
    if (exchange.providerId !== req.user.userId && exchange.requesterId !== req.user.userId) {
      return res.status(403).json({ error: "Accès refusé" });
    }

    // Mise à jour du statut à COMPLETED
    const updatedExchange = await prisma.exchange.update({
      where: { id },
      data: { status: 'COMPLETED' }
    });

    // Transfert des crédits : Le demandeur paie, le prestataire reçoit
    await prisma.$transaction([
      prisma.user.update({
        where: { id: exchange.requesterId },
        data: { credits: { decrement: exchange.hours } }
      }),
      prisma.user.update({
        where: { id: exchange.providerId },
        data: { credits: { increment: exchange.hours } }
      })
    ]);

    res.json({ message: "Échange validé et crédits transférés avec succès !", updatedExchange });
  } catch (error) {
    res.status(500).json({ error: "Erreur lors de la validation de l'échange" });
  }
});

// --- MESSAGERIE INTERNE ---
app.get('/api/messages/:userId', authenticateToken, async (req, res) => {
  const { userId } = req.params;
  const messages = await prisma.message.findMany({
    where: {
      OR: [
        { senderId: req.user.userId, receiverId: userId },
        { senderId: userId, receiverId: req.user.userId }
      ]
    },
    orderBy: { createdAt: 'asc' }
  });
  res.json(messages);
});

app.post('/api/messages', authenticateToken, async (req, res) => {
  const { receiverId, content } = req.body;
  const message = await prisma.message.create({
    data: { senderId: req.user.userId, receiverId, content }
  });
  res.status(201).json(message);
});

const PORT = process.env.PORT || 5000;
app.listen(PORT, () => console.log(`🚀 Serveur SEL démarré sur le port ${PORT}`));
```

