    tokenUserA = loginA.body.token;
    userAId = loginA.body.user.id;

    // Création Utilisateur B (10 crédits par défaut)
    const resB = await request(app).post('/api/auth/register').send({
      name: 'Bob', email: 'bob@sel.com', password: 'password123', city: 'Paris', neighborhood: 'Republique'
    });
    const loginB = await request(app).post('/api/auth/login').send({ email: 'bob@sel.com', password: 'password123' });
    tokenUserB = loginB.body.token;
    userBId = loginB.body.user.id;

    // Création d'une compétence par Alice
    const skillRes = await request(app)
      .post('/api/skills')
      .set('Authorization', `Bearer ${tokenUserA}`)
      .send({ title: 'Cours de Cuisine', category: 'Loisirs', description: 'Apprendre à faire des macarons' });
    skillId = skillRes.body.id;
  });

  afterAll(async () => {
