      .set('Authorization', `Bearer ${tokenUserB}`)
      .send({ providerId: userAId, skillId: newSkillRes.body.id, hours: 20 });

    const res = await request(app)
      .put(`/api/exchanges/${newEx.body.id}/complete`)
      .set('Authorization', `Bearer ${tokenUserA}`);

    expect(res.statusCode).toEqual(400);
    expect(res.body.error).toContain('Crédits insuffisants');
  });
});
