### 3. `script.js` (Interactivité & Logique Métier)

```javascript
/* ==========================================================
   DEVELOPER AGENT - SCRIPT.JS (L'Éden Impérial)
   ========================================================== */

document.addEventListener('DOMContentLoaded', () => {

    /* --- 1. NAVIGATION MOBILE (BURGER MENU) --- */
    const burger = document.querySelector('.burger');
    const navLinks = document.querySelector('.nav-links');
    const links = document.querySelectorAll('.nav-links li a');

    burger.addEventListener('click', () => {
        navLinks.classList.toggle('active');
        burger.querySelector('i').classList.toggle('fa-bars');
        burger.querySelector('i').classList.toggle('fa-times');
    });

    links.forEach(link => {
        link.addEventListener('click', () => {
            navLinks.classList.remove('active');
            burger.querySelector('i').classList.add('fa-bars');
            burger.querySelector('i').classList.remove('fa-times');
        });
    });

    /* --- 2. HEADER SCROLL EFFECT --- */
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.style.backgroundColor = 'rgba(10, 10, 10, 0.95)';
            header.style.padding = '0';
        } else {
            header.style.backgroundColor = 'rgba(10, 10, 10, 0.85)';
        }
    });

    /* --- 3. SYSTÈME DE FILTRAGE DES DESTINATIONS --- */
    const filterBtns = document.querySelectorAll('.filter-btn');
    const destCards = document.querySelectorAll('.dest-card');

    filterBtns.forEach(btn => {
        btn.addEventListener('click', () => {
            // Activer le bouton sélectionné
            filterBtns.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');

            const filterValue = btn.getAttribute('data-filter');

            destCards.forEach(card => {
                const category = card.getAttribute('data-category');

                if (filterValue === 'all' || category === filterValue) {
                    card.classList.remove('hide');
                    // Petite animation d'apparition fluide
                    card.style.opacity = '0';
                    setTimeout(() => { card.style.opacity = '1'; }, 50);
                } else {
                    card.classList.add('hide');
                }
            });
        });
    });

    /* --- 4. INTERACTION RÉSERVATION RAPIDE (DEPUIS LES CARTES) --- */
    window.openBooking = function(destinationName) {
        const selectElement = document.getElementById('destination');

        // Chercher si l'option existe, sinon la sélectionner par défaut
        for (let i = 0; i < selectElement.options.length; i++) {
            if (selectElement.options[i].value.includes(destinationName)) {
                selectElement.selectedIndex = i;
                break;
            }
        }

        // Scroll fluide vers la section de contact/réservation
        document.getElementById('contact').scrollIntoView({
            behavior: 'smooth'
        });
    };

    /* --- 5. GESTION DU FORMULAIRE DE RÉSERVATION --- */
    const bookingForm = document.getElementById('luxuryBookingForm');
    const successMsg = document.getElementById('formSuccessMessage');

    bookingForm.addEventListener('submit', (e) => {
        e.preventDefault();

        // Récupération des valeurs (simulation d'envoi API sécurisé)
        const clientName = document.getElementById('name').value;
        const clientEmail = document.getElementById('email').value;
        const chosenDest = document.getElementById('destination').value;
        const travelDate = document.getElementById('date').value;

        if(!clientName || !clientEmail || !travelDate) {
            alert('Veuillez remplir tous les champs obligatoires.');
            return;
        }

        // Affichage du message de confirmation élégant
        successMsg.classList.add('active');
        bookingForm.reset();

        // Masquer le message après 6 secondes
        setTimeout(() => {
            successMsg.classList.remove('active');
        }, 6000);
    });

    /* --- 6. ANIMATION AU DÉFILEMENT (INTERSECTION OBSERVER) --- */
    const observerOptions = {
        threshold: 0.15
    };

    const observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.style.opacity = '1';
                entry.target.style.transform = 'translateY(0)';
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Appliquer l'effet d'apparition sur les blocs principaux
    const animatedElements = document.querySelectorAll('.dest-card, .exp-item, .section-header');
    animatedElements.forEach(el => {
        el.style.opacity = '0';
        el.style.transform = 'translateY(30px)';
        el.style.transition = 'opacity 0.8s ease-out, transform 0.8s ease-out';
        observer.observe(el);
    });

});
