            <!-- Barre de recherche -->
            <div class="search-bar">
                <svg viewBox="0 0 24 24"><path d="M15.5 14h-.79l-.28-.27C15.41 12.59 16 11.11 16 9.5 16 5.91 13.09 3 9.5 3S3 5.91 3 9.5 5.91 16 9.5 16c1.61 0 3.09-.59 4.23-1.57l.27.28v.79l5 4.99L20.49 19l-4.99-5zm-6 0C7.01 14 5 11.99 5 9.5S7.01 5 9.5 5 14 7.01 14 9.5 11.99 14 9.5 14z"/></svg>
                <input type="text" id="searchInput" placeholder="Rechercher par nom, description ou code...">
            </div>

            <!-- Sélecteur de plateformes (Tabs) -->
            <div class="platform-tabs" id="platformTabs">
                <button class="tab-btn active" data-platform="ps5">PS5</button>
                <button class="tab-btn" data-platform="xbox">Xbox Series X</button>
                <button class="tab-btn" data-platform="pc">PC</button>
            </div>
        </div>

        <!-- Filtres par catégories et favoris -->
        <div class="filters-row" style="margin-bottom: 2rem;">
            <div class="category-filters" id="categoryFilters">
                <button class="filter-btn active" data-category="all">Tous</button>
                <button class="filter-btn" data-category="joueur">Joueur</button>
                <button class="filter-btn" data-category="vehicules">Véhicules</button>
                <button class="filter-btn" data-category="monde">Monde</button>
            </div>
            <button class="filter-btn" id="favoritesFilterBtn" style="display: flex; align-items: center; gap: 6px;">
                ⭐ Favoris (<span id="favoritesCount">0</span>)
            </button>
        </div>

        <!-- Grille dynamique des codes -->
        <div class="cheats-grid" id="cheatsGrid">
            <!-- Rendu injecté dynamiquement par JavaScript -->
        </div>
    </main>

    <!-- Notification Toast -->
    <div id="toast">
        <svg viewBox="0 0 24 24"><path d="M9 16.2L4.8 12l-1.4 1.4L9 19 21 7l-1.4-1.4L9 16.2z"/></svg>
        <span id="toastMessage">Code copié dans le presse-papier !</span>
    </div>

    <footer>
        <p>&copy; 2025 GTA 6 Community Project. Non affilié à Rockstar Games.</p>
    </footer>

    <script>
        /* --- JAVASCRIPT : LOGIQUE & GESTION DES DONNÉES --- */

        // Base de données locale (cheats.json intégré)
        const cheatsData = [
            {
                id: "cheat-001",
                title: "Invincibilité (Mode Dieu)",
                category: "joueur",
                description: "Rend votre personnage invulnérable aux balles et aux dégâts de chute pendant 5 minutes.",
                codes: {
                    ps5: ["TRIANGLE", "DROITE", "GAUCHE", "DROITE", "R1", "R2", "GAUCHE", "DROITE", "CARRÉ", "DROITE", "L1", "L1"],
                    xbox: ["Y", "DROITE", "GAUCHE", "DROITE", "RT", "RB", "GAUCHE", "DROITE", "X", "DROITE", "LT", "LT"],
                    pc: "PAINKILLER"
                },
                isNew: true,
                warning: "Désactive temporairement les trophées pour la session."
            },
            {
                id: "cheat-002",
                title: "Apparition de la Turismo Retro",
                category: "vehicules",
                description: "Fait apparaître instantanément une supercar sportive de course devant le joueur.",
                codes: {
                    ps5: ["R1", "CARRÉ", "R2", "DROITE", "L1", "L2", "CROIX", "CROIX", "CARRÉ", "R1"],
                    xbox: ["RB", "X", "RT", "DROITE", "LB", "LT", "A", "A", "X", "RB"],
                    pc: "TURISMO"
                },
                isNew: false,
                warning: null
            },
            {
                id: "cheat-003",
                title: "Changement de Météo (Tempête)",
                category: "monde",
                description: "Fait basculer dynamiquement le temps vers une pluie battante et des éclairs.",
                codes: {
                    ps5: ["R2", "CROIX", "L1", "L1", "L2", "L2", "L2", "CARRÉ"],
                    xbox: ["RT", "A", "LB", "LB", "LT", "LT", "LT", "X"],
                    pc: "STORM"
                },
                isNew: true,
                warning: null
            },
            {
                id: "cheat-004",
                title: "Super Saut",
                category: "joueur",
                description: "Permet au personnage de bondir dix fois plus haut qu'à la normale.",
                codes: {
                    ps5: ["GAUCHE", "GAUCHE", "TRIANGLE", "TRIANGLE", "DROITE", "DROITE", "GAUCHE", "DROITE", "CARRÉ", "R1", "R2"],
                    xbox: ["GAUCHE", "GAUCHE", "Y", "Y", "DROITE", "DROITE", "GAUCHE", "DROITE", "X", "RB", "RT"],
                    pc: "HOPTOIT"
                },
                isNew: false,
                warning: null
            },
            {
                id: "cheat-005",
                title: "Apparition de l'Hélicoptère Buzzard",
                category: "vehicules",
                description: "Fait apparaître un hélicoptère léger armé de roquettes et de mitrailleuses.",
                codes: {
                    ps5: ["CARRÉ", "CARRÉ", "L1", "CARRÉ", "CARRÉ", "CARRÉ", "L1", "L2", "R1", "TRIANGLE", "CARRÉ", "TRIANGLE"],
                    xbox: ["X", "X", "LB", "X", "X", "X", "LB", "LT", "RB", "Y", "X", "Y"],
                    pc: "BUZZOFF"
                },
                isNew: true,
                warning: null
            }
        ];

        // État de l'application
        let currentPlatform = 'ps5';
        let currentCategory = 'all';
        let showOnlyFavorites = false;
        let searchQuery = '';

        // Gestion des favoris via localStorage
        function getFavorites() {
            const favs = localStorage.getItem('gta6_favorites');
            return favs ? JSON.parse(favs) : [];
        }

        function toggleFavorite(id) {
            let favs = getFavorites();
            if (favs.includes(id)) {
                favs = favs.filter(favId => favId !== id);
            } else {
                favs.push(id);
            }
            localStorage.setItem('gta6_favorites', JSON.stringify(favs));
            updateFavoritesCount();
            renderCheats();
        }

        function updateFavoritesCount() {
            const favs = getFavorites();
            document.getElementById('favoritesCount').textContent = favs.length;
        }

        // Rendu dynamique des cartes
        function renderCheats() {
            const grid = document.getElementById('cheatsGrid');
            const favorites = getFavorites();

            // Filtrage des données
            const filtered = cheatsData.filter(cheat => {
                // Filtre favoris
                if (showOnlyFavorites && !favorites.includes(cheat.id)) return false;

                // Filtre catégorie
                if (currentCategory !== 'all' && cheat.category !== currentCategory) return false;

                // Recherche textuelle
                if (searchQuery) {
                    const query = searchQuery.toLowerCase();
                    const titleMatch = cheat.title.toLowerCase().includes(query);
                    const descMatch = cheat.description.toLowerCase().includes(query);

                    const codeVal = cheat.codes[currentPlatform];
                    const codeMatch = Array.isArray(codeVal) 
                        ? codeVal.join(' ').toLowerCase().includes(query)
                        : codeVal.toLowerCase().includes(query);

                    if (!titleMatch && !descMatch && !codeMatch) return false;
                }

                return true;
            });

            if (filtered.length === 0) {
                grid.innerHTML = `<div class="no-results"><h3>Aucun code trouvé</h3><p>Modifiez vos critères de recherche ou filtres.</p></div>`;
                return;
            }

            // Génération du HTML
            grid.innerHTML = filtered.map(cheat => {
                const isFav = favorites.includes(cheat.id);
                const codeData = cheat.codes[currentPlatform];

                // Formatage de la séquence de touches ou du code texte (PC)
                let codeHtml = '';
                let textToCopy = '';

                if (Array.isArray(codeData)) {
                    textToCopy = codeData.join(' ');
                    codeHtml = codeData.map(key => `<span class="key-badge">${key}</span>`).join(' ');
                } else {
                    textToCopy = codeData;
                    codeHtml = `<span class="key-badge" style="background: rgba(5, 217, 232, 0.1); color: var(--secondary-cyan);">${codeData}</span>`;
                }

                return `
                    <div class="cheat-card">
                        <div>
                            <div class="card-header">
                                <div class="card-badges">
                                    ${cheat.isNew ? '<span class="badge new">Nouveau</span>' : ''}
                                    <span class="badge category">${cheat.category}</span>
                                </div>
                                <button class="favorite-btn ${isFav ? 'active' : ''}" onclick="toggleFavorite('${cheat.id}')" title="Ajouter aux favoris">
                                    <svg viewBox="0 0 24 24"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"/></svg>
                                </button>
                            </div>
                            <h3>${cheat.title}</h3>
                            <p>${cheat.description}</p>
                        </div>
                        <div>
                            <div class="code-box" onclick="copyToClipboard('${textToCopy}')" title="Cliquer pour copier">
                                <div class="code-sequence">${codeHtml}</div>
                                <svg class="copy-icon" viewBox="0 0 24 24"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg>
                            </div>
                            ${cheat.warning ? `<div class="warning-text">⚠️ ${cheat.warning}</div>` : ''}
                        </div>
                    </div>
                `;
            }).join('');
        }

        // API Clipboard & Notification Toast
        function copyToClipboard(text) {
            navigator.clipboard.writeText(text).then(() => {
                showToast(`Code copié : ${text}`);
            }).catch(err => {
                console.error('Erreur lors de la copie : ', err);
            });
        }

        function showToast(message) {
            const toast = document.getElementById('toast');
            const toastMessage = document.getElementById('toastMessage');
            toastMessage.textContent = message;

            toast.classList.add('show');
            setTimeout(() => {
                toast.classList.remove('show');
            }, 2500);
        }

        // Écouteurs d'événements et initialisation
        document.addEventListener('DOMContentLoaded', () => {
            updateFavoritesCount();
            renderCheats();

            // Recherche instantanée
            document.getElementById('searchInput').addEventListener('input', (e) => {
                searchQuery = e.target.value;
                renderCheats();
            });

            // Onglets Plateforme
            document.querySelectorAll('#platformTabs .tab-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    document.querySelectorAll('#platformTabs .tab-btn').forEach(b => b.classList.remove('active'));
                    e.target.classList.add('active');
                    currentPlatform = e.target.dataset.platform;
                    renderCheats();
                });
            });

            // Filtres Catégories
            document.querySelectorAll('#categoryFilters .filter-btn').forEach(btn => {
                btn.addEventListener('click', (e) => {
                    document.querySelectorAll('#categoryFilters .filter-btn').forEach(b => b.classList.remove('active'));
                    e.target.classList.add('active');
                    currentCategory = e.target.dataset.category;
                    showOnlyFavorites = false;
                    document.getElementById('favoritesFilterBtn').classList.remove('active');
                    renderCheats();
                });
            });

            // Filtre Favoris
            const favBtn = document.getElementById('favoritesFilterBtn');
            favBtn.addEventListener('click', () => {
                showOnlyFavorites = !showOnlyFavorites;
                if (showOnlyFavorites) {
                    favBtn.classList.add('active');
                    document.querySelectorAll('#categoryFilters .filter-btn').forEach(b => b.classList.remove('active'));
                } else {
                    favBtn.classList.remove('active');
                    document.querySelector('#categoryFilters .filter-btn[data-category="all"]').classList.add('active');
                    currentCategory = 'all';
                }
                renderCheats();
            });
        });
    </script>
</body>
</html>
