document.addEventListener('DOMContentLoaded', () => {
    // --- 1. Gestion du Menu Mobile ---
    const hamburger = document.querySelector('.hamburger');
    const navMenu = document.querySelector('.nav-menu');

    hamburger.addEventListener('click', () => {
        navMenu.classList.toggle('active');
    });

    // Fermer le menu au clic sur un lien
    document.querySelectorAll('.nav-link').forEach(link => {
        link.addEventListener('click', () => {
            navMenu.classList.remove('active');
        });
    });

    // --- 2. Affichage Dynamique du Catalogue ---
    const grid = document.getElementById('destinations-grid');

    function renderDestinations(filter = 'all', searchQuery = '') {
        grid.innerHTML = '';

        const filtered = destinationsData.filter(item => {
            const matchesCategory = (filter === 'all' || item.category === filter);
            const matchesSearch = item.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
                                  item.description.toLowerCase().includes(searchQuery.toLowerCase());
            return matchesCategory && matchesSearch;
        });

        if (filtered.length === 0) {
            grid.innerHTML = `<p style="grid-column: 1/-1; text-align: center; color: var(--gray);">Aucune destination ne correspond à votre recherche.</p>`;
            return;
        }

        filtered.forEach(dest => {
            const card = document.createElement('div');
            card.className = 'destination-card';
            card.innerHTML = `
                <div class="card-img">
                    <img src="${dest.image}" alt="${dest.title}">
                    <span class="card-badge">${dest.badge}</span>
                </div>
                <div class="card-body">
                    <h3>${dest.title}</h3>
                    <p>${dest.description}</p>
                    <div class="card-footer">
                        <span class="price">Dès ${dest.price} €</span>
                        <a href="#reservation" class="btn btn-primary book-shortcut" data-title="${dest.title}">Réserver</a>
                    </div>
                </div>
            `;
            grid.appendChild(card);
        });

        // Ajouter l'interactivité sur les boutons "Réserver" des cartes pour pré-remplir le formulaire
        document.querySelectorAll('.book-shortcut').forEach(button => {
            button.addEventListener('click', (e) => {
                const title = e.target.getAttribute('data-title');
                const select = document.getElementById('dest-select');
                for (let option of select.options) {
                    if (option.text.includes(title)) {
                        select.value = option.value;
                        calculateTotal();
                        break;
                    }
                }
            });
        });
    }

    // Initialisation de la grille
    renderDestinations();

    // --- 3. Filtrage par Catégorie (Boutons) ---
    const filterButtons = document.querySelectorAll('.filter-btn');
    filterButtons.forEach(btn => {
        btn.addEventListener('click', (e) => {
            document.querySelector('.filter-btn.active').classList.remove('active');
            e.target.classList.add('active');
            const filter = e.target.getAttribute('data-filter');
            const searchQuery = document.getElementById('search-dest').value;
            renderDestinations(filter, searchQuery);
        });
    });

    // --- 4. Recherche Rapide depuis le Hero Banner ---
    const quickSearchForm = document.getElementById('quick-search-form');
    quickSearchForm.addEventListener('submit', (e) => {
        e.preventDefault();
        const searchQuery = document.getElementById('search-dest').value;
        const categoryQuery = document.getElementById('search-category').value;

        // Mettre à jour l'UI des boutons de filtre
        filterButtons.forEach(btn => {
            if (btn.getAttribute('data-filter') === (categoryQuery || 'all')) {
                btn.classList.add('active');
            } else {
                btn.classList.remove('active');
            }
        });

        renderDestinations(categoryQuery || 'all', searchQuery);

        // Scroll fluide vers la section destinations
        document.getElementById('destinations').scrollIntoView({ behavior: 'smooth' });
    });

    // --- 5. Calculateur de Prix en Temps Réel ---
    const destSelect = document.getElementById('dest-select');
    const travelersInput = document.getElementById('travelers');
    const checkboxes = document.querySelectorAll('input[name="option"]');
    const totalPriceSpan = document.getElementById('total-price');

    function calculateTotal() {
        let basePrice = 0;
        const selectedOption = destSelect.options[destSelect.selectedIndex];

        if (selectedOption && selectedOption.value) {
            basePrice = parseFloat(selectedOption.getAttribute('data-price')) || 0;
        }

        const travelers = parseInt(travelersInput.value) || 1;
        let optionsTotal = 0;

        checkboxes.forEach(box => {
            if (box.checked) {
                optionsTotal += parseFloat(box.value) || 0;
            }
        });

        const total = (basePrice * travelers) + optionsTotal;
        totalPriceSpan.textContent = `${total} €`;
    }

    destSelect.addEventListener('change', calculateTotal);
    travelersInput.addEventListener('input', calculateTotal);
    checkboxes.forEach(box => box.addEventListener('change', calculateTotal));

    // --- 6. Validation du Formulaire et Gestion de la Réservation ---
    const bookingForm = document.getElementById('booking-form');
    const modal = document.getElementById('confirmation-modal');
    const closeModalBtn = document.getElementById('close-modal');
    const modalMessage = document.getElementById('modal-message');

    bookingForm.addEventListener('submit', (e) => {
        e.preventDefault();

        // Validation basique JS
        const name = document.getElementById('fullname').value.trim();
        const email = document.getElementById('email').value.trim();
        const startDate = document.getElementById('start-date').value;

        if (!name || !email || !startDate || !destSelect.value) {
            alert('Veuillez remplir tous les champs obligatoires.');
            return;
        }

        // Personnalisation du message de confirmation
        const selectedDestText = destSelect.options[destSelect.selectedIndex].text.split(' - ')[0];
        const travelersCount = travelersInput.value;
        const finalPrice = totalPriceSpan.textContent;

        modalMessage.innerHTML = `Merci <strong>${name}</strong> ! Votre séjour pour <strong>${selectedDestText}</strong> (${travelersCount} voyageur(s)) d'un montant de <strong>${finalPrice}</strong> a bien été pris en compte. Un récapitulatif a été envoyé à <em>${email}</em>.`;

        // Afficher la modale
        modal.style.display = 'flex';
    });

    closeModalBtn.addEventListener('click', () => {
        modal.style.display = 'none';
        bookingForm.reset();
        calculateTotal();
    });

    // Fermer la modale en cliquant en dehors de celle-ci
    window.addEventListener('click', (e) => {
        if (e.target === modal) {
            modal.style.display = 'none';
        }
    });
});
