            { id: "#TX-9025", name: "Emma Roux", date: "19 Mai 2024", amount: "780.20 €", status: "active" }
        ];

        // --- RENDU DU TABLEAU ---
        const tableBody = document.getElementById("tableBody");

        function renderTable(data) {
            tableBody.innerHTML = "";
            if(data.length === 0) {
                tableBody.innerHTML = `<tr><td colspan="5" style="text-align:center; color: var(--text-muted);">Aucun résultat trouvé</td></tr>`;
                return;
            }
            data.forEach(item => {
                let statusLabel = item.status === 'active' ? 'Actif' : item.status === 'pending' ? 'En attente' : 'Inactif';
                const row = document.createElement("tr");
                row.innerHTML = `
                    <td style="font-weight: 600;">${item.id}</td>
                    <td>${item.name}</td>
                    <td>${item.date}</td>
                    <td>${item.amount}</td>
                    <td><span class="badge ${item.status}">${statusLabel}</span></td>
                `;
                tableBody.appendChild(row);
            });
        }

        // Initialisation
        renderTable(initialData);

        // --- RECHERCHE INTERACTIVE ---
        const searchInput = document.getElementById("searchInput");
        searchInput.addEventListener("input", (e) => {
            const term = e.target.value.toLowerCase();
            const filtered = initialData.filter(item => 
                item.name.toLowerCase().includes(term) || 
                item.id.toLowerCase().includes(term)
            );
            renderTable(filtered);
        });

        // --- GESTION DU THÈME (LIGHT/DARK) ---
        const themeToggle = document.getElementById("themeToggle");
        const themeIcon = document.getElementById("themeIcon");
        const htmlElement = document.documentElement;

        themeToggle.addEventListener("click", () => {
            const currentTheme = htmlElement.getAttribute("data-theme");
            if (currentTheme === "light") {
                htmlElement.setAttribute("data-theme", "dark");
                themeIcon.classList.replace("fa-moon", "fa-sun");
            } else {
                htmlElement.setAttribute("data-theme", "light");
                themeIcon.classList.replace("fa-sun", "fa-moon");
            }
        });

        // --- ACTION BOUTON ACTUALISER ---
        document.getElementById("refreshBtn").addEventListener("click", () => {
            alert("Données synchronisées avec succès !");
        });
    </script>
