### 3. `backend/server.js`
```javascript
const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');
require('dotenv').config();

const app = express();
const PORT = process.env.PORT || 5000;

app.use(cors());
app.use(express.json());

// Helper pour lire les montres
const readWatchesData = () => {
  const filePath = path.join(__dirname, 'data', 'watches.json');
  const jsonData = fs.readFileSync(filePath, 'utf-8');
  return JSON.parse(jsonData);
};

// Route: Récupérer toutes les montres ou filtrer par recherche
app.get('/api/watches', (req, res) => {
  try {
    const watches = readWatchesData();
    const { search, brand } = req.query;

    let filteredWatches = watches;
    if (search) {
      filteredWatches = filteredWatches.filter(w => 
        w.name.toLowerCase().includes(search.toLowerCase()) || 
        w.brand.toLowerCase().includes(search.toLowerCase())
      );
    }
    if (brand) {
      filteredWatches = filteredWatches.filter(w => w.brand.toLowerCase() === brand.toLowerCase());
    }

    res.json(filteredWatches);
  } catch (error) {
    res.status(500).json({ error: 'Erreur serveur lors de la récupération du catalogue.' });
  }
});

// Route: Récupérer une montre par ID
app.get('/api/watches/:id', (req, res) => {
  try {
    const watches = readWatchesData();
    const watch = watches.find(w => w.id === req.params.id);
    if (!watch) {
      return res.status(404).json({ error: 'Montre introuvable.' });
    }
    res.json(watch);
  } catch (error) {
    res.status(500).json({ error: 'Erreur serveur.' });
  }
});

// Route: Tunnel de commande sécurisé (Simulé)
app.post('/api/orders', (req, res) => {
  try {
    const { items, shippingAddress, paymentInfo } = req.body;

    if (!items || items.length === 0) {
      return res.status(400).json({ error: 'Le panier est vide.' });
    }
    if (!shippingAddress || !paymentInfo) {
      return res.status(400).json({ error: 'Informations de livraison ou de paiement manquantes.' });
    }

    // Simulation de traitement bancaire sécurisé
    const orderId = 'ORD-' + Math.floor(100000 + Math.random() * 900000);
    const totalAmount = items.reduce((sum, item) => sum + (item.price * item.quantity), 0);

    console.log(`[PAIEMENT VALIDÉ] Commande ${orderId} traitée pour un montant de ${totalAmount}€`);

    res.status(201).json({
      success: true,
      message: 'Commande validée avec succès.',
      orderId,
      totalAmount,
      estimatedDelivery: '3 à 5 jours ouvrés'
    });
  } catch (error) {
    res.status(500).json({ error: 'Erreur lors du traitement de la commande.' });
  }
});

app.listen(PORT, () => {
  console.log(`Serveur back-end démarré sur le port ${PORT}`);
});
```

