### 10. `frontend/src/App.jsx`
```jsx
import React, { useState } from 'react';
import Navbar from './components/Navbar';
import CartDrawer from './components/CartDrawer';
import Home from './pages/Home';
import Catalog from './pages/Catalog';
import ProductDetail from './pages/ProductDetail';
import Checkout from './pages/Checkout';

export default function App() {
  const [currentPage, setCurrentPage] = useState('home'); // home, catalog, detail, checkout
  const [selectedProductId, setSelectedProductId] = useState(null);
  const [cart, setCart] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);

  const handleAddToCart = (watch) => {
    setCart(prev => {
      const existing = prev.find(item => item.id === watch.id);
      if (existing) {
        return prev.map(item => item.id === watch.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...watch, quantity: 1 }];
    });
  };

  const handleUpdateQuantity = (id, quantity) => {
    if (quantity <= 0) {
      handleRemoveCartItem(id);
      return;
    }
    setCart(prev => prev.map(item => item.id === id ? { ...item, quantity } : item));
  };

  const handleRemoveCartItem = (id) => {
    setCart(prev => prev.filter(item => item.id !== id));
  };

  const cartCount = cart.reduce((sum, item) => sum + item.quantity, 0);

  const handleSelectProduct = (id) => {
    setSelectedProductId(id);
    setCurrentPage('detail');
  };

  return (
    <div className="min-h-screen bg-luxury-dark text-white flex flex-col font-sans selection:bg-luxury-gold selection:text-black">
      <Navbar 
        cartCount={cartCount} 
        onOpenCart={() => setIsCartOpen(true)} 
        setCurrentPage={setCurrentPage} 
      />

      <main className="flex-grow">
        {currentPage === 'home' && <Home onExplore={() => setCurrentPage('catalog')} />}
        {currentPage === 'catalog' && <Catalog onSelectProduct={handleSelectProduct} />}
        {currentPage === 'detail' && (
          <ProductDetail 
            productId={selectedProductId} 
            onBack={() => setCurrentPage('catalog')} 
            onAddToCart={handleAddToCart} 
          />
        )}
        {currentPage === 'checkout' && (
          <Checkout 
            cart={cart} 
            onBack={() => setCurrentPage('catalog')} 
            onOrderSuccess={() => setCart([])} 
          />
        )}
      </main>

      <CartDrawer 
        isOpen={isCartOpen} 
        onClose={() => setIsCartOpen(false)} 
        cart={cart} 
        onUpdateQuantity={handleUpdateQuantity} 
        onRemove={handleRemoveCartItem} 
        onCheckout={() => setCurrentPage('checkout')} 
      />

      <footer className="bg-luxury-gray border-t border-luxury-gold/20 py-8 text-center text-xs text-gray-500 tracking-wider">
        <p>&copy; {new Date().getFullYear()} CHRONOS & CO. - Haute Horlogerie. Tous droits réservés.</p>
      </footer>
    </div>
  );
}
```

