    },
    {
        id: 5,
        name: "Titanium Sport",
        category: "Sport",
        price: 720.00,
        image: "https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?auto=format&fit=crop&w=600&q=80",
        description: "Légère et incroyablement résistante grâce à son châssis en titane. Idéale pour le sport extrême et le quotidien."
    },
    {
        id: 6,
        name: "Abyss Blue",
        category: "Plongée",
        price: 580.00,
        image: "https://images.unsplash.com/photo-1614341996277-c15cae5c3c9d?auto=format&fit=crop&w=600&q=80",
        description: "Un cadran bleu profond rappelant l'océan, combiné à une lunette rotative unidirectionnelle en céramique anti-rayures."
    }
];

// --- ÉTAT GLOBAL (PANIER) ---
let cart = JSON.parse(localStorage.getItem('chronolux_cart')) || [];

// --- INITIALISATION AU CHARGEMENT ---
document.addEventListener('DOMContentLoaded', () => {
    renderFeaturedProducts();
    renderCatalogProducts(products);
    updateCartUI();
});

// --- GESTION DES VUES (SPA Navigation) ---
function switchView(viewId) {
    document.querySelectorAll('.view').forEach(view => {
        view.classList.remove('active');
    });

    if(viewId === 'home') {
        document.getElementById('home-view').classList.add('active');
    } else if(viewId === 'catalog') {
        document.getElementById('catalog-view').classList.add('active');
    } else if(viewId === 'detail') {
        document.getElementById('detail-view').classList.add('active');
    }
    window.scrollTo({ top: 0, behavior: 'smooth' });
}

// --- RENDU PRODUITS ---
function renderFeaturedProducts() {
    const container = document.getElementById('featured-products');
    const featured = products.slice(0, 3); // 3 premiers produits
    container.innerHTML = featured.map(product => createProductCardHTML(product)).join('');
}

function renderCatalogProducts(productsToRender) {
    const container = document.getElementById('catalog-products');
    if(productsToRender.length === 0) {
        container.innerHTML = `<p style="grid-column: 1/-1; text-align: center; color: var(--text-muted);">Aucune montre ne correspond à vos critères.</p>`;
        return;
    }
    container.innerHTML = productsToRender.map(product => createProductCardHTML(product)).join('');
}

function createProductCardHTML(product) {
    return `
        <div class="product-card">
            <img src="${product.image}" alt="${product.name}" class="product-img" onclick="showProductDetail(${product.id})">
            <div class="product-info">
                <div>
                    <span class="product-category">${product.category}</span>
                    <h3 class="product-title" onclick="showProductDetail(${product.id})">${product.name}</h3>
                    <div class="product-price">${product.price.toFixed(2)} €</div>
                </div>
                <button class="btn btn-primary btn-full" onclick="addToCart(${product.id})">Ajouter au panier</button>
            </div>
        </div>
    `;
}

// --- FILTRES CATALOGUE ---
function filterProducts() {
    const searchTerm = document.getElementById('search-input').value.toLowerCase();
    const category = document.getElementById('category-filter').value;

    const filtered = products.filter(product => {
        const matchesSearch = product.name.toLowerCase().includes(searchTerm) || product.description.toLowerCase().includes(searchTerm);
        const matchesCategory = category === 'all' || product.category === category;
        return matchesSearch && matchesCategory;
    });

    renderCatalogProducts(filtered);
}

// --- PAGE DÉTAIL PRODUIT ---
function showProductDetail(id) {
    const product = products.find(p => p.id === id);
    if (!product) return;

    const container = document.getElementById('product-detail-content');
    container.innerHTML = `
        <img src="${product.image}" alt="${product.name}" class="product-detail-img">
        <div class="product-detail-info">
            <span class="product-category">${product.category}</span>
            <h2>${product.name}</h2>
            <div class="price">${product.price.toFixed(2)} €</div>
            <p>${product.description}</p>
            <button class="btn btn-primary" onclick="addToCart(${product.id}); toggleCartDrawer();">Ajouter au panier</button>
        </div>
    `;

    switchView('detail');
}

// --- SYSTÈME DE PANIER ---
function toggleCartDrawer() {
    document.getElementById('cart-drawer').classList.toggle('open');
    document.getElementById('cart-overlay').classList.toggle('active');
}

function addToCart(productId) {
    const product = products.find(p => p.id === productId);
    const existingItem = cart.find(item => item.id === productId);

    if (existingItem) {
        existingItem.quantity += 1;
    } else {
        cart.push({ ...product, quantity: 1 });
    }

    saveCart();
    updateCartUI();
}

function removeFromCart(productId) {
    cart = cart.filter(item => item.id !== productId);
    saveCart();
    updateCartUI();
}

function changeQuantity(productId, delta) {
    const item = cart.find(item => item.id === productId);
    if (item) {
        item.quantity += delta;
        if (item.quantity <= 0) {
            removeFromCart(productId);
        } else {
            saveCart();
            updateCartUI();
        }
    }
}

function saveCart() {
    localStorage.setItem('chronolux_cart', JSON.stringify(cart));
}

function updateCartUI() {
    const badge = document.getElementById('cart-badge');
    const itemsContainer = document.getElementById('cart-items');
    const totalPriceEl = document.getElementById('cart-total-price');

    // Calcul du nombre total d'articles
    const totalCount = cart.reduce((sum, item) => sum + item.quantity, 0);
    badge.textContent = totalCount;

    // Rendu des articles dans le tiroir
    if (cart.length === 0) {
        itemsContainer.innerHTML = `<p style="text-align: center; color: var(--text-muted); margin-top: 2rem;">Votre panier est vide.</p>`;
    } else {
        itemsContainer.innerHTML = cart.map(item => `
            <div class="cart-item">
                <img src="${item.image}" alt="${item.name}">
                <div class="cart-item-details">
                    <div class="cart-item-title">${item.name}</div>
                    <div class="cart-item-price">${(item.price * item.quantity).toFixed(2)} €</div>
                    <div class="cart-item-actions">
                        <button onclick="changeQuantity(${item.id}, -1)">-</button>
                        <span>${item.quantity}</span>
                        <button onclick="changeQuantity(${item.id}, 1)">+</button>
                        <button class="remove-item" onclick="removeFromCart(${item.id})"><i class="fa-solid fa-trash-can"></i></button>
                    </div>
                </div>
            </div>
        `).join('');
    }

    // Calcul du prix total
    const totalPrice = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0);
    totalPriceEl.textContent = `${totalPrice.toFixed(2)} €`;
}

function checkout() {
    if (cart.length === 0) {
        alert("Votre panier est vide.");
        return;
    }
    alert("Merci pour votre commande ! Simulation de paiement validée.");
    cart = [];
    saveCart();
    updateCartUI();
    toggleCartDrawer();
    switchView('home');
}
```

