/* ==========================================
   LOGIQUE GÉNÉRALE & INITIALISATION
   ========================================== */
document.addEventListener("DOMContentLoaded", () => {
    highlightActiveNav();

    // Page Accueil : Afficher une sélection de voyages phares
    const featuredGrid = document.getElementById("featured-trips");
    if (featuredGrid) {
        renderTrips(voyagesCatalog.slice(0, 3), featuredGrid);
    }

    // Page Catalogue : Afficher tous les voyages et gérer les filtres
    const catalogGrid = document.getElementById("catalog-grid");
    if (catalogGrid) {
        renderTrips(voyagesCatalog, catalogGrid);
        setupCatalogFilters();
    }

    // Page FAQ : Gestion des accordéons
    setupFAQ();

    // Page de Vente (Booking) : Gestion de la configuration dynamique
    setupBookingPage();

    // Page Paiement (Checkout) : Gestion de la simulation de paiement
    setupCheckoutPage();
});

/* Surligner le lien actif dans la navbar */
function highlightActiveNav() {
    const currentPage = window.location.pathname.split("/").pop() || "index.html";
    document.querySelectorAll(".nav-links a").forEach(link => {
        if (link.getAttribute("href") === currentPage) {
            link.classList.add("active");
        }
    });
}

/* Générateur de cartes de voyages HTML */
function renderTrips(tripsArray, container) {
    container.innerHTML = tripsArray.map(trip => `
        <div class="trip-card">
            <img src="${trip.img}" alt="${trip.title}" class="trip-img">
            <div class="trip-content">
                <h3 class="trip-title">${trip.title}</h3>
                <p class="trip-desc">${trip.desc}</p>
                <div style="font-size: 0.85rem; color: var(--gray); margin-bottom: 0.5rem;">⏱️ Durée : ${trip.duration}</div>
                <div class="trip-footer">
                    <span class="trip-price">${trip.price} €</span>
                    <a href="booking.html?id=${trip.id}" class="btn" style="padding: 0.5rem 1rem; font-size: 0.9rem;">Réserver</a>
                </div>
            </div>
        </div>
    `).join("");
}

/* ==========================================
   FILTRES DU CATALOGUE
   ========================================== */
function setupCatalogFilters() {
    const searchInput = document.getElementById("search-input");
    const categorySelect = document.getElementById("category-select");
    const catalogGrid = document.getElementById("catalog-grid");

    function filterAndRender() {
        const query = searchInput.value.toLowerCase();
        const category = categorySelect.value;

        const filtered = voyagesCatalog.filter(trip => {
            const matchesQuery = trip.title.toLowerCase().includes(query) || trip.desc.toLowerCase().includes(query);
            const matchesCat = category === "all" || trip.category === category;
            return matchesQuery && matchesCat;
        });

        renderTrips(filtered, catalogGrid);
    }

    if (searchInput && categorySelect) {
        searchInput.addEventListener("input", filterAndRender);
        categorySelect.addEventListener("change", filterAndRender);
    }
}

/* ==========================================
   FAQ ACCORDÉON INTERACTIF
   ========================================== */
function setupFAQ() {
    const faqItems = document.querySelectorAll(".faq-item");
    faqItems.forEach(item => {
        const questionBtn = item.querySelector(".faq-question");
        questionBtn.addEventListener("click", () => {
            // Fermer les autres
            faqItems.forEach(other => {
                if (other !== item) other.classList.remove("active");
            });
            // Basculer l'actuel
            item.classList.toggle("active");
        });
    });
}

/* ==========================================
   PAGE DE VENTE & CONFIGURATION (BOOKING)
   ========================================== */
function setupBookingPage() {
    const summaryContainer = document.getElementById("booking-summary-content");
    if (!summaryContainer) return;

    // Récupérer l'ID du voyage dans l'URL (ex: booking.html?id=3)
    const urlParams = new URLSearchParams(window.location.search);
    const tripId = parseInt(urlParams.get("id")) || 1;
    const selectedTrip = voyagesCatalog.find(t => t.id === tripId) || voyagesCatalog[0];

    // Éléments du DOM du formulaire
    const travelersInput = document.getElementById("travelers");
    const insuranceSelect = document.getElementById("insurance");
    const totalPriceEl = document.getElementById("total-price");
    const proceedBtn = document.getElementById("proceed-checkout-btn");

    function calculateTotal() {
        const travelers = parseInt(travelersInput.value) || 1;
        const insuranceCost = insuranceSelect.value === "yes" ? 150 * travelers : 0;
        const total = (selectedTrip.price * travelers) + insuranceCost;

        summaryContainer.innerHTML = `
            <h3>${selectedTrip.title}</h3>
            <p style="color:var(--gray); font-size:0.9rem; margin: 0.5rem 0 1rem 0;">Durée : ${selectedTrip.duration}</p>
            <div class="summary-item"><span>Prix de base</span> <span>${selectedTrip.price} € / pers.</span></div>
            <div class="summary-item"><span>Voyageurs</span> <span>x ${travelers}</span></div>
            <div class="summary-item"><span>Assurance Annulation</span> <span>${insuranceSelect.value === "yes" ? 150 * travelers + ' €' : 'Non'}</span></div>
            <div class="summary-total">Total : ${total} €</div>
        `;

        // Sauvegarder les données de la commande pour la page de paiement
        localStorage.setItem("currentBooking", JSON.stringify({
            title: selectedTrip.title,
            travelers,
            total
        }));
    }

    travelersInput.addEventListener("input", calculateTotal);
    insuranceSelect.addEventListener("change", calculateTotal);
    calculateTotal();

    proceedBtn.addEventListener("click", (e) => {
        e.preventDefault();
        window.location.href = "checkout.html";
    });
}

/* ==========================================
   PAGE DE PAIEMENT SÉCURISÉ (CHECKOUT)
   ========================================== */
function setupCheckoutPage() {
    const checkoutSummary = document.getElementById("checkout-summary");
    if (!checkoutSummary) return;

    const bookingData = JSON.parse(localStorage.getItem("currentBooking"));
    if (bookingData) {
        checkoutSummary.innerHTML = `
            <p><strong>Voyage :</strong> ${bookingData.title}</p>
            <p><strong>Nombre de voyageurs :</strong> ${bookingData.travelers}</p>
            <p style="font-size: 1.25rem; font-weight: bold; color: var(--primary); margin-top: 0.5rem;">Montant à régler : ${bookingData.total} €</p>
        `;
    }

    // Gestion de la sélection du mode de paiement
    const methodCards = document.querySelectorAll(".payment-method-card");
    methodCards.forEach(card => {
        card.addEventListener("click", () => {
            methodCards.forEach(c => c.classList.remove("selected"));
            card.classList.add("selected");
        });
    });

    // Simulation de la validation du formulaire de paiement
    const paymentForm = document.getElementById("payment-form");
    const successModal = document.getElementById("success-modal");

    paymentForm.addEventListener("submit", (e) => {
        e.preventDefault();
        // Validation JS basique simulée avec succès
        successModal.style.display = "flex";
    });
}
