// État Global de l'Application
let currentTripId = 1;
let selectedTravelers = 1;
let selectedFlightOption = 0;

// Gestion du routage et de l'affichage SPA
document.addEventListener('DOMContentLoaded', () => {
    initRouter();
    setupBurgerMenu();
});

function setupBurgerMenu() {
    const burger = document.getElementById('burger');
    const navMenu = document.getElementById('navMenu');
    burger.addEventListener('click', () => {
        navMenu.classList.toggle('active');
    });
}

function initRouter() {
    const navLinks = document.querySelectorAll('.nav-link');

    navLinks.forEach(link => {
        link.addEventListener('click', (e) => {
            e.preventDefault();
            const target = e.target.getAttribute('data-target');

            navLinks.forEach(l => l.classList.remove('active'));
            e.target.classList.add('active');

            // Fermer le menu mobile si ouvert
            document.getElementById('navMenu').classList.remove('active');

            renderPage(target);
        });
    });

    // Page initiale
    renderPage('home');
}

function navigateTo(pageName, param = null) {
    document.querySelectorAll('.nav-link').forEach(l => {
        if(l.getAttribute('data-target') === pageName) {
            l.classList.add('active');
        } else {
            l.classList.remove('active');
        }
    });
    renderPage(pageName, param);
    window.scrollTo(0,0);
}

function renderPage(page, param) {
    const main = document.getElementById('main-content');
    main.innerHTML = '';

    switch(page) {
        case 'home':
            main.innerHTML = renderHomePage();
            setupHomeEvents();
            break;
        case 'catalog':
            main.innerHTML = renderCatalogPage();
            break;
        case 'configurator':
            main.innerHTML = renderConfiguratorPage(param || currentTripId);
            setupConfiguratorEvents();
            break;
        case 'faq':
            main.innerHTML = renderFaqPage();
            setupFaqEvents();
            break;
        case 'checkout':
            main.innerHTML = renderCheckoutPage();
            setupCheckoutEvents();
            break;
        default:
            main.innerHTML = '<h2>Page non trouvée</h2>';
    }
}

