// ==========================================

function setupConfiguratorEvents() {
    const tripSelect = document.getElementById('tripSelect');
    const travelersInput = document.getElementById('travelersCount');
    const flightSelect = document.getElementById('flightOption');
    const proceedBtn = document.getElementById('proceedToCheckout');

    function updateSummary() {
        const tripId = parseInt(tripSelect.value);
        const trip = tripsData.find(t => t.id === tripId);
        selectedTravelers = parseInt(travelersInput.value) || 1;
        const flightCost = parseInt(flightSelect.value);

        document.getElementById('sumTitle').textContent = trip.title;
        document.getElementById('sumDuration').textContent = trip.duration;
        document.getElementById('sumBasePrice').textContent = trip.price;
        document.getElementById('sumTravelers').textContent = selectedTravelers;
        document.getElementById('sumFlight').textContent = flightCost * selectedTravelers;

        const total = (trip.price * selectedTravelers) + (flightCost * selectedTravelers);
        document.getElementById('sumTotal').textContent = total;
    }

    tripSelect.addEventListener('change', updateSummary);
    travelersInput.addEventListener('input', updateSummary);
    flightSelect.addEventListener('change', updateSummary);

    proceedBtn.addEventListener('click', () => {
        currentTripId = parseInt(tripSelect.value);
        navigateTo('checkout');
    });
}

function setupFaqEvents() {
    const headers = document.querySelectorAll('.accordion-header');
    headers.forEach(header => {
        header.addEventListener('click', () => {
            const item = header.parentElement;
            item.classList.toggle('active');
        });
    });
}

function setupCheckoutEvents() {
    const form = document.getElementById('paymentForm');
    form.addEventListener('submit', (e) => {
        e.preventDefault();
        const wrapper = document.getElementById('checkoutFormWrapper');
        wrapper.innerHTML = `
            <div class="confirmation-box">
                <h2>🎉 Paiement Validé avec Succès !</h2>
                <p>Merci pour votre réservation. Un e-mail de confirmation vient de vous être envoyé avec tous les détails de votre voyage.</p>
                <br>
                <button class="btn" onclick="navigateTo('home')">Retour à l'Accueil</button>
            </div>
        `;
    });
}
```

