#### `/js/main.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {
    // 1. Gestion du Menu Burger Mobile
    const burger = document.querySelector('.burger');
    const navLinks = document.querySelector('.nav-links');

    if (burger && navLinks) {
        burger.addEventListener('click', () => {
            navLinks.classList.toggle('active');
            const icon = burger.querySelector('i');
            if (navLinks.classList.contains('active')) {
                burger.textContent = '✕';
            } else {
                burger.textContent = '☰';
            }
        });
    }

    // 2. Validation du Formulaire de Contact
    const contactForm = document.getElementById('contactForm');
    const formFeedback = document.getElementById('formFeedback');

    if (contactForm) {
        contactForm.addEventListener('submit', (e) => {
            e.preventDefault();

            const name = document.getElementById('name').value.trim();
            const email = document.getElementById('email').value.trim();
            const message = document.getElementById('message').value.trim();

            if (name === '' || email === '' || message === '') {
                showFeedback('Veuillez remplir tous les champs obligatoires.', 'error');
                return;
            }

            if (!validateEmail(email)) {
                showFeedback('Veuillez entrer une adresse email valide.', 'error');
                return;
            }

            // Simulation d'envoi réussi
            showFeedback('Merci ! Votre message a bien été envoyé au Bertangles Darts Club.', 'success');
            contactForm.reset();
        });
    }

    function validateEmail(email) {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(email);
    }

    function showFeedback(msg, type) {
        if (!formFeedback) return;
        formFeedback.textContent = msg;
        formFeedback.style.padding = '10px';
        formFeedback.style.marginTop = '15px';
        formFeedback.style.borderRadius = '4px';

        if (type === 'error') {
            formFeedback.style.backgroundColor = 'rgba(230, 57, 70, 0.2)';
            formFeedback.style.color = '#e63946';
        } else {
            formFeedback.style.backgroundColor = 'rgba(40, 167, 69, 0.2)';
            formFeedback.style.color = '#28a745';
        }
    }
});
```

