```jsx
import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { destinations } from '../data/destinationsData';
import { CheckCircle2 } from 'lucide-react';

export default function Booking() {
  const { id } = useParams();
  const navigate = useNavigate();
  const destination = destinations.find(d => d.id === parseInt(id));

  const [submitted, setSubmitted] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    travelers: 1,
    date: ''
  });

  if (!destination) return <div className="text-center py-20">Destination introuvable.</div>;

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  if (submitted) {
    return (
      <div className="max-w-md mx-auto px-4 py-20 text-center">
        <CheckCircle2 className="w-16 h-16 text-green-500 mx-auto mb-4" />
        <h2 className="text-2xl font-bold text-gray-900 mb-2">Réservation Confirmée !</h2>
        <p className="text-gray-600 mb-6">Merci {formData.name}. Un email de confirmation a été envoyé à {formData.email}.</p>
        <button onClick={() => navigate('/')} className="bg-brand-600 text-white px-6 py-2 rounded-lg font-medium hover:bg-brand-700">
          Retour à l'accueil
        </button>
      </div>
    );
  }

  const totalPrice = destination.price * formData.travelers;

  return (
    <div className="max-w-2xl mx-auto px-4 py-12">
      <h1 className="text-3xl font-bold text-gray-900 mb-2">Réservation en Ligne</h1>
      <p className="text-gray-600 mb-8">Vous réservez : <span className="font-semibold text-brand-600">{destination.title}</span></p>

      <form onSubmit={handleSubmit} className="bg-white p-8 rounded-2xl shadow-md space-y-6">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Nom complet</label>
          <input type="text" name="name" required value={formData.name} onChange={handleChange} className="w-full p-3 border rounded-lg focus:outline-none focus:border-brand-600" />
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Email</label>
            <input type="email" name="email" required value={formData.email} onChange={handleChange} className="w-full p-3 border rounded-lg focus:outline-none focus:border-brand-600" />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Téléphone</label>
            <input type="tel" name="phone" required value={formData.phone} onChange={handleChange} className="w-full p-3 border rounded-lg focus:outline-none focus:border-brand-600" />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Nombre de voyageurs</label>
            <input type="number" name="travelers" min="1" max="10" value={formData.travelers} onChange={handleChange} className="w-full p-3 border rounded-lg focus:outline-none focus:border-brand-600" />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">Date de départ souhaitée</label>
            <input type="date" name="date" required value={formData.date} onChange={handleChange} className="w-full p-3 border rounded-lg focus:outline-none focus:border-brand-600" />
          </div>
        </div>

        <div className="bg-gray-50 p-4 rounded-xl flex justify-between items-center">
          <span className="font-medium text-gray-700">Total estimé :</span>
          <span className="text-2xl font-bold text-brand-600">{totalPrice}€</span>
        </div>

        <button type="submit" className="w-full bg-brand-600 text-white font-bold py-3 rounded-xl shadow-md hover:bg-brand-700 transition">
          Confirmer et payer
        </button>
      </form>
    </div>
  );
}
