### 3. `script.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {

    /* ==========================================================
       1. MENU MOBILE (BURGER)
       ========================================================== */
    const burger = document.querySelector('.burger');
    const navLinks = document.querySelector('.nav-links');
    const navItems = document.querySelectorAll('.nav-links li');

    burger.addEventListener('click', () => {
        // Basculer la navigation
        navLinks.classList.toggle('nav-active');

        // Animation du bouton burger
        burger.classList.toggle('toggle');
    });

    // Fermer le menu mobile lorsqu'on clique sur un lien
    navItems.forEach(item => {
        item.addEventListener('click', () => {
            navLinks.classList.remove('nav-active');
            burger.classList.remove('toggle');
        });
    });


    /* ==========================================================
       2. FILTRE DE L'ÉQUIPE (TEAM FILTER)
       ========================================================== */
    const filterButtons = document.querySelectorAll('.filter-btn');
    const teamCards = document.querySelectorAll('.team-card');

    filterButtons.forEach(button => {
        button.addEventListener('click', () => {
            // Retirer la classe active de tous les boutons
            filterButtons.forEach(btn => btn.classList.remove('active'));
            // Ajouter la classe active au bouton cliqué
            button.classList.add('active');

            const filterValue = button.getAttribute('data-filter');

            teamCards.forEach(card => {
                const category = card.getAttribute('data-category');

                if (filterValue === 'all' || category === filterValue) {
                    card.style.display = 'block';
                    // Petit effet d'apparition fluide
                    card.style.opacity = '0';
                    setTimeout(() => {
                        card.style.opacity = '1';
                    }, 50);
                } else {
                    card.style.display = 'none';
                }
            });
        });
    });


    /* ==========================================================
       3. VALIDATION DYNAMIQUE DU FORMULAIRE DE CONTACT
       ========================================================== */
    const contactForm = document.getElementById('contactForm');
    const nameInput = document.getElementById('name');
    const emailInput = document.getElementById('email');
    const subjectInput = document.getElementById('subject');
    const messageInput = document.getElementById('message');
    const formSuccess = document.getElementById('formSuccess');

    contactForm.addEventListener('submit', (e) => {
        e.preventDefault(); // Empêche la soumission réelle par défaut

        let isValid = true;

        // Validation du Nom
        if (nameInput.value.trim() === '') {
            setError(nameInput, 'Le nom est obligatoire.');
            isValid = false;
        } else {
            setSuccess(nameInput);
        }

        // Validation de l'Email
        if (emailInput.value.trim() === '') {
            setError(emailInput, "L'email est obligatoire.");
            isValid = false;
        } else if (!isValidEmail(emailInput.value.trim())) {
            setError(emailInput, "Veuillez entrer une adresse email valide.");
            isValid = false;
        } else {
            setSuccess(emailInput);
        }

        // Validation du Sujet
        if (subjectInput.value.trim() === '') {
            setError(subjectInput, 'Le sujet est obligatoire.');
            isValid = false;
        } else {
            setSuccess(subjectInput);
        }

        // Validation du Message
        if (messageInput.value.trim() === '') {
            setError(messageInput, 'Le message ne peut pas être vide.');
            isValid = false;
        } else if (messageInput.value.trim().length < 10) {
            setError(messageInput, 'Le message doit contenir au moins 10 caractères.');
            isValid = false;
        } else {
            setSuccess(messageInput);
        }

        // Si tout est valide, on simule l'envoi réussi
        if (isValid) {
            contactForm.reset();
            // Réinitialiser les classes de succès des inputs
            document.querySelectorAll('.form-group').forEach(group => {
                group.classList.remove('success');
            });

            formSuccess.style.display = 'block';
            setTimeout(() => {
                formSuccess.style.display = 'none';
            }, 5000);
        }
    });

    // Fonctions utilitaires pour le formulaire
    function setError(input, message) {
        const formGroup = input.parentElement;
        const errorMsg = formGroup.querySelector('.error-msg');
        errorMsg.innerText = message;
        formGroup.className = 'form-group error';
    }

    function setSuccess(input) {
        const formGroup = input.parentElement;
        formGroup.className = 'form-group success';
    }

    function isValidEmail(email) {
        const re = /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
        return re.test(String(email).toLowerCase());
    }

});
