### 3. Fichier `script.js`

```javascript
document.addEventListener('DOMContentLoaded', () => {

    /* ==========================================
       1. Gestion de la barre de navigation & Menu Mobile
       ========================================== */
    const header = document.getElementById('header');
    const mobileMenuBtn = document.getElementById('mobile-menu');
    const navLinks = document.querySelector('.nav-links');

    // Effet de scroll sur la navbar
    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.classList.add('scrolled');
        } else {
            header.classList.remove('scrolled');
        }
    });

    // Toggle menu mobile
    mobileMenuBtn.addEventListener('click', () => {
        navLinks.classList.toggle('active');
        const icon = mobileMenuBtn.querySelector('i');
        if (navLinks.classList.contains('active')) {
            icon.classList.remove('fa-bars');
            icon.classList.add('fa-times');
        } else {
            icon.classList.remove('fa-times');
            icon.classList.add('fa-bars');
        }
    });

    // Fermer le menu mobile lors du clic sur un lien
    document.querySelectorAll('.nav-links a').forEach(link => {
        link.addEventListener('click', () => {
            navLinks.classList.remove('active');
            const icon = mobileMenuBtn.querySelector('i');
            icon.classList.remove('fa-times');
            icon.classList.add('fa-bars');
        });
    });

    /* ==========================================
       2. Validation du formulaire et Confirmation
       ========================================== */
    const bookingForm = document.getElementById('booking-form');
    const formMessage = document.getElementById('form-message');

    // Définir la date minimale du formulaire à aujourd'hui
    const dateInput = document.getElementById('date');
    const today = new Date().toISOString().split('T')[0];
    dateInput.setAttribute('min', today);

    bookingForm.addEventListener('submit', (e) => {
        e.preventDefault();

        // Récupération des valeurs
        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        const date = document.getElementById('date').value;
        const time = document.getElementById('time').value;
        const participants = document.getElementById('participants').value;
        const kartChoiceSelect = document.getElementById('kart-choice');
        const kartChoiceText = kartChoiceSelect.options[kartChoiceSelect.selectedIndex].text;

        // Validation simple côté client
        if (!name || !email || !date || !time || !participants || !kartChoiceSelect.value) {
            showFormMessage('Veuillez remplir tous les champs du formulaire.', 'error');
            return;
        }

        // Simulation d'un traitement réussi (ex: appel API backend)
        setTimeout(() => {
            showFormMessage(`Merci ${name} ! Votre réservation pour ${participants} personne(s) en kart "${kartChoiceText}" le ${date} à ${time} a bien été enregistrée. Un e-mail de confirmation a été envoyé à ${email}.`, 'success');
            bookingForm.reset();
        }, 500);
    });

    function showFormMessage(message, type) {
        formMessage.textContent = message;
        formMessage.classList.remove('hidden');

        if (type === 'error') {
            formMessage.style.backgroundColor = 'rgba(255, 51, 102, 0.2)';
            formMessage.style.border = '1px solid var(--primary)';
            formMessage.style.color = '#ff8fa3';
        } else {
            formMessage.className = 'success';
            formMessage.style.backgroundColor = '';
            formMessage.style.border = '';
            formMessage.style.color = '';
        }
    }

    /* ==========================================
       3. Animation au défilement (Scroll Animations)
       ========================================== */
    const observerOptions = {
        threshold: 0.15
    };

    const observer = new IntersectionObserver((entries, observer) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                entry.target.classList.add('fade-in');
                observer.unobserve(entry.target);
            }
        });
    }, observerOptions);

    // Sélectionner les éléments à animer
    const animatedElements = document.querySelectorAll('.kart-card, .pricing-card, .reservation-wrapper');
    animatedElements.forEach(el => {
        el.style.opacity = '0';
        observer.observe(el);
    });
});
```

