```javascript
document.addEventListener('DOMContentLoaded', () => {
    // 1. Menu Mobile Hamburger
    const hamburger = document.querySelector('.hamburger');
    const navLinks = document.querySelector('.nav-links');

    hamburger.addEventListener('click', () => {
        navLinks.classList.toggle('active');
        const icon = hamburger.querySelector('i');
        icon.classList.toggle('fa-bars');
        icon.classList.toggle('fa-times');
    });

    // Fermer le menu mobile lors du clic sur un lien
    document.querySelectorAll('.nav-links a').forEach(link => {
        link.addEventListener('click', () => {
            navLinks.classList.remove('active');
            const icon = hamburger.querySelector('i');
            icon.classList.add('fa-bars');
            icon.classList.remove('fa-times');
        });
    });

    // 2. Système de filtrage des pistes
    const filterButtons = document.querySelectorAll('.filter-btn');
    const trackCards = document.querySelectorAll('.track-card');

    filterButtons.forEach(button => {
        button.addEventListener('click', () => {
            // Retirer la classe active de tous les boutons
            filterButtons.forEach(btn => btn.classList.remove('active'));
            // Ajouter la classe active au bouton cliqué
            button.classList.add('active');

            const filterValue = button.getAttribute('data-filter');

            trackCards.forEach(card => {
                const category = card.getAttribute('data-category');
                if (filterValue === 'all' || category === filterValue) {
                    card.style.display = 'block';
                    setTimeout(() => card.style.opacity = '1', 50);
                } else {
                    card.style.opacity = '0';
                    setTimeout(() => card.style.display = 'none', 300);
                }
            });
        });
    });

    // 3. Gestion et validation du formulaire de réservation
    const bookingForm = document.getElementById('bookingForm');
    const formMessage = document.getElementById('formMessage');

    // Définir la date minimale à aujourd'hui pour le champ date
    const dateInput = document.getElementById('date');
    const today = new Date().toISOString().split('T')[0];
    dateInput.setAttribute('min', today);

    bookingForm.addEventListener('submit', (e) => {
        e.preventDefault();

        const name = document.getElementById('name').value.trim();
        const email = document.getElementById('email').value.trim();
        const track = document.getElementById('track').value;
        const date = document.getElementById('date').value;
        const pilots = document.getElementById('pilots').value;

        if (!name || !email || !track || !date || !pilots) {
            formMessage.style.color = '#e74c3c';
            formMessage.textContent = 'Veuillez remplir tous les champs du formulaire.';
            return;
        }

        // Simulation d'un envoi réussi avec effet visuel
        formMessage.style.color = '#2ecc71';
        formMessage.innerHTML = `<i class="fas fa-check-circle"></i> Félicitations ${name} ! Votre réservation pour ${pilots} pilote(s) le ${date} est confirmée. Un email de confirmation a été envoyé à ${email}.`;

        // Réinitialisation du formulaire
        bookingForm.reset();

        // Effacer le message après 6 secondes
        setTimeout(() => {
            formMessage.textContent = '';
        }, 6000);
    });
});
