fy-content: space-between;\n    align-items: center;\n    height: 80px;\n}\n\n.logo {\n    font-size: 1.8rem;\n    font-weight: 900;\n    letter-spacing: 1px;\n    color: #fff;\n}\n\n.logo span {\n    color: var(--primary);\n}\n\n.nav-links {\n    display: flex;\n    gap: 30px;\n}\n\n.nav-links a {\n    font-weight: 600;\n    transition: var(--transition);\n}\n\n.nav-links a:hover, .nav-links a.active {\n    color: var(--primary);\n}\n\n.hamburger {\n    display: none;\n    font-size: 1.8rem;\n    cursor: pointer;\n}\n\n/* Hero Section */\n.hero {\n    height: 100vh;\n    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.7)), url('https://images.unsplash.com/photo-1568605117036-5fe5e7bab0b7?auto=format&fit=crop&w=1920&q=80') no-repeat center center/cover;\n    display: flex;\n    align-items: center;\n    text-align: center;\n    padding-top: 80px;\n}\n\n.hero-content {\n    max-width: 800px;\n    margin: 0 auto;\n}\n\n.hero-content h1 {\n    font-size: 3.5rem;\n    text-transform: uppercase;\n    margin-bottom: 20px;\n    letter-spacing: 2px;\n}\n\n.hero-content p {\n    font-size: 1.2rem;\n    color: #ddd;\n    margin-bottom: 40px;\n}\n\n.hero-buttons {\n    display: flex;\n    justify-content: center;\n    gap: 20px;\n}\n\n/* Section Pistes */\n.filter-buttons {\n    display: flex;\n    justify-content: center;\n    gap: 15px;\n    margin-bottom: 40px;\n}\n\n.filter-btn {\n    background-color: var(--dark-card);\n    color: #fff;\n    border: none;\n    padding: 10px 20px;\n    border-radius: 30px;\n    cursor: pointer;\n    font-weight: 600;\n    transition: var(--transition);\n}\n\n.filter-btn.active, .filter-btn:hover {\n    background-color: var(--primary);\n}\n\n.tracks-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));\n    gap: 30px;\n}\n\n.track-card {\n    background-color: var(--dark-card);\n    border-radius: 10px;\n    overflow: hidden;\n    box-shadow: 0 5px 15px rgba(0,0,0,0.3);\n    transition: var(--transition);\n}\n\n.track-card:hover {\n    transform: translateY(-10px);\n}\n\n.track-img {\n    height: 220px;\n    background-size: cover;\n    background-position: center;\n    position: relative;\n    padding: 15px;\n}\n\n.badge {\n    position: absolute;\n    top: 15px;\n    right: 15px;\n    padding: 5px 12px;\n    border-radius: 20px;\n    font-size: 0.8rem;\n    font-weight: bold;\n    text-transform: uppercase;\n}\n\n.badge.indoor {\n    background-color: #3498db;\n    color: #fff;\n}\n\n.badge.outdoor {\n    background-color: #e67e22;\n    color: #fff;\n}\n\n.track-info {\n    padding: 25px;\n}\n\n.track-info h3 {\n    font-size: 1.5rem;\n    margin-bottom: 10px;\n}\n\n.track-info p {\n    color: var(--gray);\n    font-size: 0.95rem;\n    margin-bottom: 15px;\n}\n\n.track-info .desc {\n    color: #ccc;\n    margin-bottom: 20px;\n}\n\n.btn-card {\n    color: var(--primary);\n    font-weight: bold;\n    transition: var(--transition);\n}\n\n.btn-card:hover {\n    color: #fff;\n}\n\n/* Section Tarifs */\n.pricing-grid {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));\n    gap: 30px;\n    align-items: center;\n}\n\n.price-card {\n    background-color: var(--dark-card);\n    border-radius: 10px;\n    padding: 40px 30px;\n    text-align: center;\n    position: relative;\n    box-shadow: 0 5px 15px rgba(0,0,0,0.3);\n    transition: var(--transition);\n}\n\n.price-card.popular {\n    border: 2px solid var(--primary);\n    transform: scale(1.05);\n}\n\n.popular-badge {\n    position: absolute;\n    top: -15px;\n    left: 50%;\n    transform: translateX(-50%);\n    background-color: var(--primary);\n    color: #fff;\n    padding: 5px 15px;\n    font-size: 0.8rem;\n    font-weight: bold;\n    border-radius: 20px;\n    text-transform: uppercase;\n}\n\n.price-card h3 {\n    font-size: 1.8rem;\n    margin-bottom: 15px;\n}\n\n.price {\n    font-size: 2.5rem;\n    font-weight: 900;\n    color: var(--primary);\n    margin-bottom: 25px;\n}\n\n.price span {\n    font-size: 1rem;\n    color: var(--gray);\n    font-weight: normal;\n}\n\n.price-card ul {\n    margin-bottom: 30px;\n    text-align: left;\n}\n\n.price-card ul li {\n    margin-bottom: 15px;\n    color: #ccc;\n    font-size: 0.95rem;\n}\n\n.price-card ul li i.fa-check {\n    color: #2ecc71;\n    margin-right: 10px;\n}\n\n.price-card ul li i.fa-times {\n    color: #e74c3c;\n    margin-right: 10px;\n}\n\n/* Section Réservation */\n.reservation {\n    background-color: #181818;\n}\n\n.booking-form {\n    max-width: 700px;\n    margin: 0 auto;\n    background-color: var(--dark-card);\n    padding: 40px;\n    border-radius: 10px;\n    box-shadow: 0 5px 20px rgba(0,0,0,0.4);\n}\n\n.form-group {\n    margin-bottom: 20px;\n}\n\n.form-group label {\n    display: block;\n    margin-bottom: 8px;\n    font-weight: 600;\n}\n\n.form-group label i {\n    color: var(--primary);\n    margin-right: 8px;\n}\n\n.form-group input, .form-group select {\n    width: 100%;\n    padding: 12px 15px;\n    background-color: var(--dark);\n    border: 1px solid #333;\n    border-radius: 5px;\n    color: #fff;\n    font-size: 1rem;\n}\n\n.form-group input:focus, .form-group select:focus {\n    outline: none;\n    border-color: var(--primary);\n}\n\n.form-message {\n    text-align: center;\n    margin-top: 20px;\n    font-weight: bold;\n    font-size: 1.1rem;\n}\n\n/* Footer */\n.footer {\n    background-color: #0b0b0b;\n    padding: 60px 0 20px;\n}\n\n.footer-content {\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n    gap: 40px;\n    margin-bottom: 40px;\n}\n\n.footer-col h4 {\n    font-size: 1.2rem;\n    margin-bottom: 20px;\n    text-transform: uppercase;\n    letter-spacing: 1px;\n}\n\n.footer-col p {\n    color: var(--gray);\n    margin-bottom: 15px;\n    font-size: 0.95rem;\n}\n\n.footer-col p i {\n    color: var(--primary);\n    margin-right: 10px;\n}\n\n.social-links {\n    display: flex;\n    gap: 15px;\n}\n\n.social-links a {\n    display: flex;\n    align-items: center;\n    justify-content: center;\n    width: 40px;\n    height: 40px;\n    background-color: var(--dark-card);\n    border-radius: 50%;\n    transition: var(--transition);\n}\n\n.social-links a:hover {\n    background-color: var(--primary);\n    transform: translateY(-3px);\n}\n\n.footer-bottom {\n    text-align: center;\n    padding-top: 20px;\n    border-top: 1px solid #222;\n    color: var(--gray);\n    font-size: 0.9rem;\n}\n\n/* Responsive Design */\n@media (max-width: 768px) {\n    .nav-links {\n        position: absolute;\n        top: 80px;\n        left: -100%;\n        width: 100%;\n        height: calc(100vh - 80px);\n        background-color: var(--dark);\n        flex-direction: column;\n        align-items: center;\n        justify-content: center;\n        transition: var(--transition);\n    }\n\n    .nav-links.active {\n        left: 0;\n    }\n\n    .hamburger {\n        display: block;\n    }\n\n    .hero-content h1 {\n        font-size: 2.5rem;\n    }\n\n    .hero-buttons {\n        flex-direction: column;\n        gap: 15px;\n    }\n\n    .price-card.popular {\n        transform: none;\n    }\n}"
