### Fichier : `script.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {

    /* MENU MOBILE TOGGLE */
    const hamburger = document.querySelector('.hamburger');
    const navbar = document.querySelector('.navbar');
    const navLinks = document.querySelectorAll('.nav-links a');

    hamburger.addEventListener('click', () => {
        hamburger.classList.toggle('active');
        navbar.classList.toggle('active');
    });

    // Fermer le menu mobile lorsqu'un lien est cliqué
    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            hamburger.classList.remove('active');
            navbar.classList.remove('active');
        });
    });

    /* EFFET NAVBAR AU DÉFILEMENT (STICKY) */
    const header = document.querySelector('.header');

    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.style.backgroundColor = 'rgba(10, 10, 12, 0.95)';
            header.style.boxShadow = '0 5px 20px rgba(0, 0, 0, 0.5)';
        } else {
            header.style.backgroundColor = 'rgba(10, 10, 12, 0.85)';
            header.style.boxShadow = 'none';
        }
    });

    /* NAVIGATION ACTIVE AU DÉFILEMENT */
    const sections = document.querySelectorAll('section');

    window.addEventListener('scroll', () => {
        let current = '';
        sections.forEach(section => {
            const sectionTop = section.offsetTop;
            const sectionHeight = section.clientHeight;
            if (pageYOffset >= (sectionTop - sectionHeight / 3)) {
                current = section.getAttribute('id');
            }
        });

        navLinks.forEach(link => {
            link.classList.remove('active');
            if (link.getAttribute('href') === `#${current}`) {
                link.classList.add('active');
            }
        });
    });

    /* VALIDATION DU FORMULAIRE DE CONTACT */
    const contactForm = document.getElementById('contactForm');
    const formSuccess = document.getElementById('formSuccess');

    if (contactForm) {
        contactForm.addEventListener('submit', (e) => {
            e.preventDefault();
            let isValid = true;

            // Validation simple des champs
            const name = document.getElementById('name');
            const email = document.getElementById('email');
            const subject = document.getElementById('subject');
            const message = document.getElementById('message');

            // Réinitialisation des erreurs
            [name, email, subject, message].forEach(field => {
                field.parentElement.classList.remove('error');
            });

            if (name.value.trim() === '') {
                name.parentElement.classList.add('error');
                isValid = false;
            }

            if (email.value.trim() === '' || !isValidEmail(email.value)) {
                email.parentElement.classList.add('error');
                isValid = false;
            }

            if (subject.value === '') {
                subject.parentElement.classList.add('error');
                isValid = false;
            }

            if (message.value.trim() === '') {
                message.parentElement.classList.add('error');
                isValid = false;
            }

            if (isValid) {
                // Simulation d'envoi réussi
                contactForm.reset();
                formSuccess.classList.add('active');

                setTimeout(() => {
                    formSuccess.classList.remove('active');
                }, 5000);
            }
        });
    }

    function isValidEmail(email) {
        const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return re.test(String(email).toLowerCase());
    }
});
