### Fichier : ⁠`script.js`
```javascript
document.addEventListener('DOMContentLoaded', () => {

    /* =========================================
       1. MENU MOBILE RESPONSIVE
       ========================================= */
    const hamburger = document.querySelector('.hamburger');
    const navbar = document.querySelector('.navbar');
    const navLinks = document.querySelectorAll('.nav-links a');

    hamburger.addEventListener('click', () => {
        hamburger.classList.toggle('active');
        navbar.classList.toggle('active');
    });

    // Fermer le menu mobile lorsqu'un lien est cliqué
    navLinks.forEach(link => {
        link.addEventListener('click', () => {
            hamburger.classList.remove('active');
            navbar.classList.remove('active');
        });
    });

    /* =========================================
       2. EFFET DE DÉFILEMENT FLUIDE & HEADER ACTIF
       ========================================= */
    const header = document.getElementById('header');

    window.addEventListener('scroll', () => {
        if (window.scrollY > 50) {
            header.style.padding = '5px 0';
            header.style.backgroundColor = 'rgba(10, 10, 10, 0.95)';
        } else {
            header.style.padding = '0';
            header.style.backgroundColor = 'rgba(10, 10, 10, 0.9)';
        }
    });

    // Smooth scroll géré en natif via CSS (scroll-behavior: smooth), 
    // enrichi ici par JS pour compatibilité approfondie si nécessaire.
    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
        anchor.addEventListener('click', function(e) {
            const targetId = this.getAttribute('href');
            if (targetId === '#') return;

            const targetElement = document.querySelector(targetId);
            if (targetElement) {
                e.preventDefault();
                targetElement.scrollIntoView({
                    behavior: 'smooth'
                });
            }
        });
    });

    /* =========================================
       3. VALIDATION ROBUSTE DU FORMULAIRE DE CONTACT
       ========================================= */
    const contactForm = document.getElementById('contactForm');
    const formSuccess = document.getElementById('formSuccess');

    if (contactForm) {
        contactForm.addEventListener('submit', (e) => {
            e.preventDefault();

            // Récupération des champs
            const nameInput = document.getElementById('name');
            const emailInput = document.getElementById('email');
            const subjectInput = document.getElementById('subject');
            const messageInput = document.getElementById('message');

            let isValid = true;

            // Validation du Nom
            if (nameInput.value.trim() === '') {
                setError(nameInput);
                isValid = false;
            } else {
                setSuccess(nameInput);
            }

            // Validation de l'Email
            if (emailInput.value.trim() === '' || !isValidEmail(emailInput.value.trim())) {
                setError(emailInput);
                isValid = false;
            } else {
                setSuccess(emailInput);
            }

            // Validation de l'Objet
            if (subjectInput.value === '') {
                setError(subjectInput);
                isValid = false;
            } else {
                setSuccess(subjectInput);
            }

            // Validation du Message
            if (messageInput.value.trim() === '') {
                setError(messageInput);
                isValid = false;
            } else {
                setSuccess(messageInput);
            }

            // Si tout est valide, simulation d'envoi réussi
            if (isValid) {
                formSuccess.classList.remove('hidden');
                contactForm.reset();

                // Supprimer les états de succès visuels après un délai
                setTimeout(() => {
                    formSuccess.classList.add('hidden');
                    document.querySelectorAll('.form-group').forEach(group => {
                        group.classList.remove('error');
                    });
                }, 5000);
            }
        });
    }

    function setError(input) {
        const formGroup = input.parentElement;
        formGroup.classList.add('error');
    }

    function setSuccess(input) {
        const formGroup = input.parentElement;
        formGroup.classList.remove('error');
    }

    function isValidEmail(email) {
        const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return regex.test(email);
    }
});
