### Fichier : `script.js`
```javascript
// Sélection des éléments de l'affichage
const previousOperandElement = document.getElementById('previous-operand');
const currentOperandElement = document.getElementById('current-operand');
const keys = document.querySelector('.calculator-keys');

// Classe pour gérer la logique de la calculatrice
class Calculator {
    constructor(previousOperandElement, currentOperandElement) {
        this.previousOperandElement = previousOperandElement;
        this.currentOperandElement = currentOperandElement;
        this.clear();
    }

    // Réinitialise les valeurs
    clear() {
        this.currentOperand = '0';
        this.previousOperand = '';
        this.operation = undefined;
    }

    // Supprime le dernier chiffre
    delete() {
        if (this.currentOperand === 'Erreur') {
            this.clear();
            return;
        }
        if (this.currentOperand.length === 1) {
            this.currentOperand = '0';
        } else {
            this.currentOperand = this.currentOperand.slice(0, -1);
        }
    }

    // Ajoute un chiffre ou un point décimal
    appendNumber(number) {
        if (this.currentOperand === 'Erreur') {
            this.currentOperand = '';
        }
        if (number === '.' && this.currentOperand.includes('.')) return;
        if (this.currentOperand === '0' && number !== '.') {
            this.currentOperand = number;
        } else {
            this.currentOperand += number;
        }
    }

    // Choisit l'opération mathématique
    chooseOperation(operation) {
        if (this.currentOperand === 'Erreur') return;
        if (this.currentOperand === '') return;
        if (this.previousOperand !== '') {
            this.compute();
        }
        this.operation = operation;
        this.previousOperand = this.currentOperand;
        this.currentOperand = '';
    }

    // Effectue le calcul
    compute() {
        let computation;
        const prev = parseFloat(this.previousOperand);
        const current = parseFloat(this.currentOperand);

        if (isNaN(prev) || isNaN(current)) return;

        switch (this.operation) {
            case '+':
                computation = prev + current;
                break;
            case '-':
                computation = prev - current;
                break;
            case '*':
                computation = prev * current;
                break;
            case '÷':
                if (current === 0) {
                    this.currentOperand = 'Erreur';
                    this.operation = undefined;
                    this.previousOperand = '';
                    return;
                }
                computation = prev / current;
                break;
            default:
                return;
        }

        // Gestion de la précision pour éviter les erreurs de virgule flottante
        this.currentOperand = Math.round(computation * 100000000) / 100000000;
        this.currentOperand = this.currentOperand.toString();
        this.operation = undefined;
        this.previousOperand = '';
    }

    // Formate les nombres pour l'affichage (séparateur de milliers optionnel, etc.)
    getDisplayNumber(number) {
        if (number === 'Erreur') return 'Erreur';
        const stringNumber = number.toString();
        const integerDigits = parseFloat(stringNumber.split('.')[0]);
        const decimalDigits = stringNumber.split('.')[1];
        let integerDisplay;

        if (isNaN(integerDigits)) {
            integerDisplay = '';
        } else {
            integerDisplay = integerDigits.toLocaleString('fr', { maximumFractionDigits: 0 });
        }

        if (decimalDigits != null) {
            return `${integerDisplay}.${decimalDigits}`;
        } else {
            return integerDisplay;
        }
    }

    // Met à jour l'interface utilisateur
    updateDisplay() {
        this.currentOperandElement.innerText = this.getDisplayNumber(this.currentOperand);
        if (this.operation != null) {
            this.previousOperandElement.innerText = `${this.getDisplayNumber(this.previousOperand)} ${this.operation}`;
        } else {
            this.previousOperandElement.innerText = '';
        }
    }
}

// Initialisation de la calculatrice
const calculator = new Calculator(previousOperandElement, currentOperandElement);

// Écouteur d'événements sur les touches de la calculatrice
keys.addEventListener('click', event => {
    const button = event.target;
    if (!button.classList.contains('key')) return;

    if (button.classList.contains('number')) {
        calculator.appendNumber(button.innerText);
        calculator.updateDisplay();
    }

    if (button.classList.contains('operator') && !button.classList.contains('equals')) {
        let action = button.dataset.action;
        let opSymbol = button.innerText;
        calculator.chooseOperation(opSymbol);
        calculator.updateDisplay();
    }

    if (button.classList.contains('equals')) {
        calculator.compute();
        calculator.updateDisplay();
    }

    if (button.dataset.action === 'clear') {
        calculator.clear();
        calculator.updateDisplay();
    }

    if (button.dataset.action === 'delete') {
        calculator.delete();
        calculator.updateDisplay();
    }
});
