```javascript
const express = require('express');
const cors = require('cors');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 5000;

app.use(cors());
app.use(express.json());

const getTripsData = () => {
  const filePath = path.join(__dirname, 'data', 'trips.json');
  const fileData = fs.readFileSync(filePath, 'utf-8');
  return JSON.parse(fileData);
};

app.get('/api/trips', (req, res) => {
  try {
    const data = getTripsData();
    res.json(data.trips);
  } catch (error) {
    res.status(500).json({ error: 'Erreur lors de la récupération des voyages' });
  }
});

app.get('/api/trips/:id', (req, res) => {
  try {
    const data = getTripsData();
    const tripId = parseInt(req.params.id);
    const trip = data.trips.find(t => t.id === tripId);

    if (!trip) {
      return res.status(404).json({ error: 'Voyage non trouvé' });
    }

    res.json(trip);
  } catch (error) {
    res.status(500).json({ error: 'Erreur serveur' });
  }
});

app.post('/api/checkout', (req, res) => {
  const { cart, customer, payment } = req.body;
  if (!cart || !customer) {
    return res.status(400).json({ error: 'Données de commande incomplètes' });
  }
  // Simulation de traitement de paiement réussi
  const orderId = 'ORD-' + Math.floor(100000 + Math.random() * 900000);
  res.json({
    success: true,
    orderId,
    message: 'Commande validée avec succès ! Bon voyage avec Odyssée.'
  });
});

app.listen(PORT, () => {
  console.log(`Serveur démarré sur le port ${PORT}`);
});
