      </div>

      <div className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 mb-12 grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="relative">
          <Search className="absolute left-4 top-3.5 w-5 h-5 text-slate-400" />
          <input 
            type="text" 
            placeholder="Rechercher une destination, un titre..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:border-sky-600 text-sm"
          />
        </div>
        <div>
          <select 
            value={category}
            onChange={(e) => setCategory(e.target.value)}
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:border-sky-600 text-sm font-medium text-slate-700"
          >
            <option value="All">Toutes les catégories</option>
            <option value="Aventure">Aventure</option>
            <option value="Culture">Culture</option>
            <option value="Safari">Safari</option>
            <option value="Détente">Détente</option>
            <option value="Road Trip">Road Trip</option>
          </select>
        </div>
        <div>
          <select 
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:outline-none focus:border-sky-600 text-sm font-medium text-slate-700"
          >
            <option value="price-asc">Prix : croissant</option>
            <option value="price-desc">Prix : décroissant</option>
            <option value="title">Nom alphabétique</option>
          </select>
        </div>
      </div>

      {filteredTrips.length === 0 ? (
        <div className="text-center py-20 bg-white rounded-2xl border border-slate-100">
          <p className="text-slate-500 text-lg">Aucun voyage ne correspond à vos critères de recherche.</p>
